; Modified by gdh48k - Based on the disassebly by obo
;
; Disassembled by obo
;
; Differences from original release:
;   6009: C0->00 - disable protection check on FRAMES sysvar after loading
;   7E91: B0->05 - new LSB of JP (HL) instruction (below)
;   7E92: 5C->D5 - new MSB of JP (HL) instruction
;   971F: D4->D3 - fixed typo in congratulations message
;   D505: 00->E9 - JP (HL) instruction moved from printer buffer

display:        equ &4000
attrs:          equ &5800
sysvar_FRAMES:  equ &5c78

                org &5e00

; Menu Table Offsets
; 0: selection, 1 attrs, 3:ycoords, 5:options, 7:copyright, 9:header, 11:count. 12:xcoord

main_menu_data: 
main_selection  db 0
                dw main_attrs, main_ycoords, main_options, main_copyright, main_header 
main_count      db &07
main_xcoords    db &58


main_attrs:     db  &45, &45, &45, &45, &45, &45, &47
main_ycoords:   db  &10, &28, &40, &58, &70, &88, &a0

main_options:   db  '1  KEYBOAR'
                db  &c4
                db  '2  KEMPSTON JOYSTIC'
                db  &cb
                db  '3  CURSOR   JOYSTIC'
                db  &cb
                db  '4  KNIGH'
                db  &d4
                db  '5  WIZAR'
                db  &c4
                db  '6  SER'
                db  &c6
                db  '0  STAR'
                db  &d4

main_copyright: db  &47
                db  '%1983 A.C.G. ALL RIGHTS RESERVE'
                db  &c4

main_header:    db  &47
                db  'ATICATAC GAME SELECTIO'
                db  &ce

mod_menu_data:  
mod_selection   db 0
                dw mod_attrs, mod_ycoords, mod_options, mod_copyright, mod_header
mod_count       db &07
mod_xcoords     db &08

mod_attrs:      db  &47, &47, &47, &47, &47, &47, &47 
mod_ycoords:    db  &10, &28, &40, &58, &70, &88, &a0 

mod_options:    db  '1  CLASSIC MOD'
                db  &c5
                db  '2  EXPLORER MODE - OPEN CASTL'
                db  &c5
                db  '3  MINI MODE FOR ORLA/BERTI'
                db  &c5
                db  '4  TB'
                db  &c3
                db  '5  AUTO-PICKU'
                db  &d0
                db  '6  RANDOM STAR'
                db  &d4  
                db  '0  ENTE'
                db  &d2

mod_copyright:  db  &44
                db  '%2026 GDH48K NO RIGHTS RESERVE'
                db  &c4

mod_header:    db  &44
               db  '    THE SECRET PASSAG'
               db  &c5

;main_selection: db  0
;mod_selection:  db  0
current_menu:   dw  0
charset_addr:   dw  0
