in_handlers:    db  0                         ; flag set but never read
rand8:          dw  0                         ; only low 8 bits are meaningfully random
                ds  9
width_bytes:    db  0
height_lines:   db  0
counter_low:    db  0
counter_high:   db  0
game_flags:     db  0                         ; b0 set if room content drawn
saved_graphic:  db  0
