visited_rooms:  ds  20                        ; visit rooms bit array
visited_percent:db  0
food_ptr:       dw  0


                org &6000
start:
                di
                ld      sp, main_selection
                ld      a, (sysvar_FRAMES+1)
                cp      &25                  ; is frames MSB as expected?
                nop ; was RET NZ for copy-protection check
                jp      reset_menu

