draw_all_maps_manual:
        ; --- Floor 0 (Caves) ---
        ld      a, go_mapcv_y
        ld      (current_floor_y), a
        ld      a, go_mapcv_x
        ld      (current_floor_x), a
        ld      hl, minimap_cv
        call    draw_single_map_no_inc

        ; --- Floor 1 (Basement) ---
        ld      a, go_mapbm_y
        ld      (current_floor_y), a
        ld      a, go_mapbm_x
        ld      (current_floor_x), a
        ld      hl, minimap_bm
        call    draw_single_map_no_inc

        ; --- Floor 2 (Ground Floor) ---
        ld      a, go_mapgf_y
        ld      (current_floor_y), a
        ld      a, go_mapgf_x
        ld      (current_floor_x), a
        ld      hl, minimap_gf
        call    draw_single_map_no_inc

        ; --- Floor 3 (First Floor) ---
        ld      a, go_mapf1_y
        ld      (current_floor_y), a
        ld      a, go_mapf1_x
        ld      (current_floor_x), a
        ld      hl, minimap_f1
        call    draw_single_map_no_inc

        ; --- Floor 4 (Attic) ---
        ld      a, go_mapat_y
        ld      (current_floor_y), a
        ld      a, go_mapat_x
        ld      (current_floor_x), a
        ld      hl, minimap_at
        call    draw_single_map_no_inc

        ld      hl, minimap_gf          
        ld      (minimap_ptr),  hl      ; default minimap_ptr for next game

        ret

; --- Helper: Draw without auto-incrementing X ---
draw_single_map_no_inc:
        ld      (minimap_ptr), hl
        call    draw_minimap_unvisited
        ret

; =============================================================================
; draw_minimap_unvisited
; -----------------------------------------------------------------------------
; DESCRIPTION:
;    Iterates through a floor's room table and draws the "unvisited" version
;    (a single center dot) for every defined room. This is used to create the
;    background schematic for the Game Over "Quest So Far" replay.
;
; INPUT:
;    (minimap_ptr) = Pointer to the start of the floor's room table (e.g., minimap_gf)
;
; OUTPUT:
;    None (Draws directly to the screen)
;
; REGISTER USAGE:
;    AF, BC, DE, IX (IX is used as the table pointer)
; =============================================================================
draw_minimap_unvisited:
    ld      ix, (minimap_ptr)    ; Load the floor table address into IX

.dmuloop:
    ; --- 1. End of Table Check ---
    ld      a, (ix+0)            ; Get the Room ID
    cp      &FF                  ; Is it the end-of-table marker?
    ret     z                    ; If yes, return to caller

    ; --- 2. Extract Coordinates ---
    ld      d, (ix+1)            ; D = Room Relative X
    ld      e, (ix+2)            ; E = Room Relative Y

    ; --- 3. Draw the Dot ---
    ; This routine handles the internal +1 offset and screen address 
    ; calculation for a single 1x1 pixel.
    call    draw_unvisited_room

    ; --- 4. Advance to Next Entry ---
.nextrm:
    ld      bc, 3                ; Each room entry is 3 bytes [ID, X, Y]
    add     ix, bc               ; Move IX to the next entry
    jr      .dmuloop             ; Repeat until &FF is reached



run_replay:
        ld      a, &FF                 ; Force a mismatch
        ld      (current_floor), a     ; The "Dirty" flag
        ld      hl, minimap_gf
        ld      (minimap_ptr),  hl
        
        ; --- New Safe Loop Setup ---
        ld      a, (history_count)     ; Get exactly how many rooms were logged
        and     a                      ; Is it 0?
        ret     z                      ; If no rooms logged, exit immediately
        ;ld      b, a                   ; Put the total count into B for counting down
        
        ld      hl, room_history       ; Start of the actual path taken

.next_id:
        ld      a, (hl)                ; Get the Room ID
        push    hl                     ; Save history pointer
        
        ; --- 1. Identify Floor & Set Replay Anchors ---
        ; We use the Room ID (A) to update our pointers and screen positions
        
        push    af
        ld      (player_room), a        ; Temporarily set player_room for check_floor

        call    check_floor             

.offsets_join:
        call    update_replay_offsets  ; Set the GO anchors (NOT side panel)
        pop     af
        
        ld      c, a                   ; C = Room ID to find in the table
        
        ; --- 2. Search correct floor table ---
        ld      ix, (minimap_ptr)      ; IX = current floor's definition table
.search:
        ld      a, (ix+0)
        cp      &FF
        jr      z, .dmnot_found
        cp      c
        jr      z, .dmfound
        
        ld      de, 3
        add     ix, de
        jr      .search

.dmfound:
        ; --- 1. Extract Room Coordinates ---
        ld      d, (ix+1)              ; rel_x
        ld      e, (ix+2)              ; rel_y

        ; --- 1. HOLLOW (Border Only) ---
        push    de
        call    draw_visited_room      ; Draw the perimeter
        pop     de

        ; --- AUDIO ADDITION 1 ---
        push    de                      ; Guard registers from sound routine
        call    walk_sound              ; Plays click (takes approx 4 frames of CPU time)
        pop     de

        ld      b, 1                    ; ADJUSTED: Reduced from 5 to 1 (Sound handles the rest!)
        call    wait_frames

        ; --- 2. FILLED (The "Pop") ---
        push    de
        call    draw_room_center       ; Plot just the (+1, +1) pixel
        pop     de

        ; --- AUDIO ADDITION 2 ---
        push    de
        call    walk_sound              ; Plays alternating step click
        pop     de

        ld      b, 6                    ; ADJUSTED: Reduced from 10 to 6 to absorb the beep time
        call    wait_frames

        ; --- 3. HOLLOW (The Trail) ---
        ld      a, e
        inc     a                      ; Y + 1
        ld      h, a
        ld      a, d
        inc     a                      ; X + 1
        ld      l, a
        call    erase_pixel_at_coords  ; Punch the hole
        
        ld      b, 2
        call    wait_frames

.dmnot_found:
        pop     hl                     ; Restore history pointer
        inc     hl                     ; Point to next history slot
        
        ; --- RAM-Based Destruction Loop ---
        ld      a, (history_count)
        dec     a                      ; Subtract 1 from total rooms remaining
        ld      (history_count), a     ; Write back to RAM
        jp      nz, .next_id           ; Jump if rooms remain (Bypasses DJNZ limits

        ret                            
        


;----------------------------------------------------------
; draw_room_center (The "px1y1" logic)
; Input: D=rel_x, E=rel_y
;----------------------------------------------------------
draw_room_center:
        ld      a, e
        inc     a               ; Y + 1
        ld      h, a
        ld      a, d
        inc     a               ; X + 1
        ld      l, a
        jp      draw_pixel      ; Jump to your standard pixel plotter

;----------------------------------------------------------
; erase_pixel_at_coords
; Input: H=rel_y, L=rel_x (Calculates using CURRENT anchors)
;----------------------------------------------------------
erase_pixel_at_coords:
        ld      c, l                ; Save rel_x in C
        ld      b, h                ; Save rel_y in B

        ; --- 1. Calculate Absolute Y ---
        ld      a, (map_anchor_y) 
        ld      hl, current_floor_y
        add     a, (hl)           
        add     a, b                ; Anchor + Nudge + Rel_Y
        ld      d, a                ; D = Final Absolute Y

        ; --- 2. Calculate Absolute X ---
        ld      a, (map_anchor_x) 
        ld      hl, current_floor_x
        add     a, (hl)           
        add     a, c                ; Anchor + Nudge + Rel_X
        ld      l, a                ; L = Final Absolute X
        ld      h, d                ; H = Final Absolute Y

        call    pixel_address       ; Returns HL=Addr, B=Bit
        
        ; --- 3. The Mask Logic ---
        ld      a, &80
        inc     b
.eploop:  dec     b
        jr      z, .epdone
        rrca
        jr      .eploop
.epdone:  cpl
        and     (hl)
        ld      (hl), a
        ret



;----------------------------------------------------------
; wait_frames
; Purpose: Pauses execution for B frames (1/50th sec each)
; Entry:   B = Number of frames to wait
; Corrupts: AF, B
;----------------------------------------------------------
wait_frames:
        halt                ; Wait for the VSync interrupt
        djnz    wait_frames ; Decrement B and jump back if not zero
        ret



; =============================================================================
; update_replay_offsets
; -----------------------------------------------------------------------------
; DESCRIPTION:
;    Sets the screen anchors for the Game Over "Quest So Far" display.
;    Unlike the side-panel version, this uses the center-screen coordinates.
;
; INPUT:
;    A = Current Floor ID (floor_gf, floor_bm, etc.)
;
; OUTPUT:
;    Updates (current_floor_x) and (current_floor_y)
; =============================================================================
update_replay_offsets:
        cp      floor_gf
        jr      z, .set_rgf
        cp      floor_f1
        jr      z, .set_rf1
        cp      floor_at
        jr      z, .set_rat
        cp      floor_bm
        jr      z, .set_rbm
        cp      floor_cv
        jp      z, .set_rcv
        ret

.set_rgf:
        ld      a, go_mapgf_x
        ld      (current_floor_x), a
        ld      a, go_mapgf_y
        ld      (current_floor_y), a
        ret         

.set_rf1:
        ld      a, go_mapf1_x
        ld      (current_floor_x), a
        ld      a, go_mapf1_y
        ld      (current_floor_y), a
        ret

.set_rat:
        ld      a, go_mapat_x
        ld      (current_floor_x), a
        ld      a, go_mapat_y
        ld      (current_floor_y), a
        ret

.set_rbm:
        ld      a, go_mapbm_x
        ld      (current_floor_x), a
        ld      a, go_mapbm_y
        ld      (current_floor_y), a
        ret

.set_rcv:
        ld      a, go_mapcv_x
        ld      (current_floor_x), a
        ld      a, go_mapcv_y
        ld      (current_floor_y), a
        ret

; =============================================================================
; Routine:  replay_item_history & replay_item_attrs
; Baseline: Restored to working layout from image_30f0eb.png
; =============================================================================
replay_item_history:
                ld      a, (item_count)
                and     a
                ret     z                       ; Exit if 0 items collected

                ld      b, a                    ; B = Loop counter
                ld      c, 6                    ; C = Starting Attribute Column (6)
                ld      hl, item_history        ; HL = Head of array
                ld      de, &5830               ; Original Y/X layout from image_30f0eb.png

loop_items:
                push    bc                      ; [Stack 1] Save Loop/Column
                push    de                      ; [Stack 2] Save Pixel X/Y
                push    hl                      ; [Stack 3] Save history pointer

                ; --- 1. EXTRACT POINTER TO ITEM STRUCTURE ---
                ld      a, (hl)
                inc     hl
                ld      h, (hl)
                ld      l, a                    ; HL points directly to item data

                ; --- 2. POPULATE WORKSPACE WITH TARGET DATA ---
                ld      ix, entity_to_draw      
                ld      a, (hl)                 ; Offset 0: Graphic ID
                ld      (ix+0), a               

                ld      a, d                    
                ld      (ix+4), a               ; Original working baseline
                ld      a, e
                ld      (ix+3), a               ; Current X pixel

                ; --- 3. EXTRACT COLOR & MASK TO BLACK PAPER ---
                inc     hl
                inc     hl
                inc     hl
                inc     hl                      ; Advance to Offset 4 (Color Attribute)
                ld      a, (hl)                 ; Read native attribute
                
                and     &07                     ; Keep Ink colors only
                or      &40                     ; Bright bit on (Paper is Black)
                ld      (ix+5), a               ; Store attribute in workspace

                ; --- 4. RENDER SPRITE PIXELS ---
                call    draw_entity             ; Draw pixel image onto screen

                ; --- 5. RE-ALIGN STACKS AND PAINT ATTRIBUTES ---
                pop     hl                      
                pop     de                      
                pop     bc                      
                push    bc                      
                push    de                      
                push    hl                      

                ;call    replay_item_attrs       ; Color block placement fix

                pop     hl                      
                pop     de                      
                pop     bc                      

                ; --- 6. ADVANCE LAYOUT STRIDE ---
                inc     hl                      ; Next item address in history
                inc     hl                      

                ld      a, e
                add     a, 16                   ; Shift X pixel 16 units right
                ld      e, a                    

                inc     c
                inc     c                       ; Shift Attribute Column 2 cells right

                djnz    loop_items              
                ret

; =============================================================================
; Inputs:   C = Active Column Tracker, (ix+5) = Attribute color byte
; Updates:  Targets Character Rows 11, 12, 13 to clear the map area perfectly.
; =============================================================================
replay_item_attrs:
                ld      a, (ix+5)               ; A = Masked Attribute Byte
                ld      e, c
                ld      d, 0                    ; DE = Column offset

                ; --- ROW 11 ---
                ld      hl, &5960               ; Moved down to align with sprites
                add     hl, de                  
                ld      (hl), a                 
                inc     hl
                ld      (hl), a                 

                ; --- ROW 12 ---
                ld      hl, &5980               
                add     hl, de
                ld      (hl), a                 
                inc     hl
                ld      (hl), a                 

                ; --- ROW 13 ---
                ld      hl, &59A0               
                add     hl, de
                ld      (hl), a                 
                inc     hl
                ld      (hl), a                 
                ret


; food item handler
h_food:
                call    save_entity          ; save entity position for undraw
                call    check_touching       ; touching food?
                jr      c, loc_8C6E          ; jump if so
                jp      draw_16x16           ; draw 16x16 entity
loc_8C6E:
                call    undraw_entity
                ld      (ix+0), 0            ; remove food item
                call    eat_sound
                ld      c, &40               ; food adds 64 health
                ld      a, (player_energy)
                add     a, c                 ; add food value
                jr      c, loc_8C84
                cp      &f0                 ; exceeded maximum?
                jr      c, loc_8C86          ; jump if not
loc_8C84:
                ld      a, &f0              ; cap energy at maximum
loc_8C86:
                ld      (player_energy), a
                jp      draw_chicken         ; draw chicken energy bar

; flash score on game start
flash_score:
                dec     a                    ; timer expired?
                ld      (flash_timer), a     ; score flash timer
                jr      z, loc_8CA7          ; jump if so (stop flash)
                and     &0f                  ; 16th frame?
                call    z, start_beep        ; call if so (beep)
                ld      hl,  timer_attr_yx   ; MOD: Offset changed from &10c8 to &10d0 (moved one char to right)
                call    xy_to_attr           ; convert pixel coords in HL to attribute address
                ld      b, 5                 ; MOD: No of chars to flash changed from 6 to 5 (first digit removed)
loc_8C9F:
                ld      a, (hl)
                or      &80                  ; enable flash attribute
                ld      (hl), a
                inc     hl
                djnz    loc_8C9F
                ret
loc_8CA7:
                ld      hl,  timer_attr_yx
                call    xy_to_attr           ; convert pixel coords in HL to attribute address
                ld      b, 5
loc_8CAF:
                ld      a, (hl)
                and     &7f                  ; disable flash attribute
                ld      (hl), a
                inc     hl
                djnz    loc_8CAF
                ret

; player appear handler for game start
h_player_appear:
                ld      a, (flash_timer)     ; score flash timer
                and     a                    ; score flash timer active?
                jr      nz, flash_score      ; jump if so
                ld      a, (sysvar_FRAMES)
                and     3                    ; 0 in range 0-3?
                jp      nz, loc_8D12         ; jump if not
                inc     (ix+6)               ; increase drawn height
                ld      a, (ix+7)            ; player spawn sprite
                call    get_sprite_addr      ; return address of sprite A in DE
                ld      a, (de)              ; normal player sprite height
                cp      (ix+6)               ; reached full reveal height?
                jr      z, loc_8D32          ; jump if so
loc_8CD4:
                push    de
                push    hl
                ld      b, h
                ld      c, l
                ld      a, (ix+4)
                ld      (ix+2), a
                sub     (ix+6)
                ld      (ix+4), a
                ld      l, (ix+6)
                ld      h, 0
                add     hl, hl
                add     hl, de
                ld      a, h
                ld      (bc), a
                dec     bc
                ld      a, l
                ld      (bc), a
                push    hl
                ld      c, (hl)
                ld      b, (ix+0)
                push    bc
                ld      (hl), 1
                ld      a, (ix+7)            ; player spawn sprite
                ld      (ix+0), a            ; set player graphic
                call    draw_entity          ; draw entity graphic (no attrs)
                pop     bc
                pop     hl
                ld      (hl), c
                ld      (ix+0), b
                ld      a, (ix+2)
                ld      (ix+4), a
                pop     hl
                pop     de
                ld      (hl), d
                dec     hl
                ld      (hl), e
loc_8D12:
                ld      a, (ix+5)
                push    af
                ld      a, (sysvar_FRAMES)
                rrca
                rrca                         ; 1/4 colour change rate
                and     7                    ; ink 0-7
                jr      nz, loc_8D20         ; jump if not black
                inc     a                    ; convert black to blue
loc_8D20:
                or      &40                  ; add bright bit
                ld      (ix+5), a            ; set player attr
                ld      a, (ix+6)
                call    set_appear_w_h       ; set spawn appearance width/height
                pop     af
                ld      (ix+5), a
                jp      appear_sound         ; player appearance sound
loc_8D32:
                ld      a, (ix+7)            ; player spawn sprite
                ld      (ix+0), a            ; set player graphic
                ld      (ix+6), 0            ; no x movement
                ld      (ix+7), 0            ; no y movement
                ld      (ix+2), 0            ; no auto-steps
                ret

; player death animation handler
h_death:
                ld      a, (sysvar_FRAMES)
                and     3                    ; 3/4 animation rate for death
                jr      z, loc_8D12          ; jump if colouring this frame instead
                dec     (ix+6)               ; reduce player visible height
                jp      m, loc_8D5B          ; jump if after zero
                ld      a, (ix+7)            ; player spawn sprite
                call    get_sprite_addr      ; return address of sprite A in DE
                jp      loc_8CD4
loc_8D5B:
                call    place_tombstone      ; place a tombstone at the player position
                jp      prepare_player       ; prepare player to spawn

; copy initial game state to working state area
reset_game_state:
                
                ld      hl, player_init      ; initial game state
                ld      de, player           ; working game state
                ld      bc, &1570            ; 0x10000-player, rather than real init data size!
                ldir
                

                xor     a
                ld      (acg_key_flag), a ; <--- MANUALLY RESET OUR FLAG

                ; --- Reset UI Anchors to Side Panel ---
                ld      a, minimap_x         
                ld      (map_anchor_x), a
                ld      a, minimap_y         
                ld      (map_anchor_y), a
        
                ; Reset the "Last Room" so the minimap redraws fresh
                ld      a, &FF
                ld      (last_room_saved), a
                

                ; --- Brute Force History Wipe ---
                ld      hl, room_history
                ld      (hl), &FF            ; Set the first byte to "End of List"
                ld      de, room_history + 1
                ld      bc, replay_max       ; 
                ldir                         ; Smear &FF to the end
        
                ; Kill the stale pointer so 'erase_center_pixel' doesn't remove last game room
                xor     a
                ld      (pixel_addr_save),  a
                ld      (pixel_addr_save+1),a
                ; Reset the index to the start
                ld    (history_count),      a   
                ld    (item_count),         a
                ; --- Clean Item History Buffer ---
                ld      hl, item_history        ; Point to start of buffer
                ld      (hl), a                 ; Set first byte to 0
                ld      de, item_history    ; Point to second byte
                ld      bc, (item_max * 4)  ; Remaining size of buffer
                ldir
                
                
                ret  





; reduce auto-walk counter
auto_walk_step:
                ld      a, (ix+2)
                and     &0f                  ; auto-walk active?
                ret     z                    ; return if not
                dec     (ix+2)               ; take a step
                ret

; read controls and apply player movement
control_player:
                ld      a, (player_room)
                ld      (some_room+1), a     ; blank entity?
                push    bc
                push    de
                push    hl
                call    auto_walk_step       ; reduce auto-walk counter
                ld      a, (ix+2)
                or      &30                  ; can move left/right or up/down
                ld      (ix+2), a
                call    save_entity          ; save entity position for undraw
                call    read_controls        ; return controls in A (FUDLR order, negative logic)
                ld      c, a                 ; FUDLR
                pop     hl
                ld      de, 0                ; no movement yet
                bit     1, c                 ; left pressed?
                jr      nz, loc_8D9E         ; jump if not
                ld      a, b
                neg                          ; negate for left
                ld      e, a
loc_8D9E:
                bit     0, c                 ; right pressed?
                jr      nz, loc_8DA3         ; jump if not
                ld      e, b
loc_8DA3:
                bit     2, c                 ; down pressed?
                jr      nz, loc_8DA8         ; jump if not
                ld      d, b
loc_8DA8:
                bit     3, c                 ; up pressed?
                jr      nz, loc_8DB0         ; jump if not
                ld      a, b
                neg                          ; negate for up
                ld      d, a
loc_8DB0:
                pop     hl                   ; DE value from function entry
                call    slow_player          ; decelerate player movement
                pop     hl                   ; BC value from function entry
                call    move_player          ; apply player movement, including auto-walk
                call    chk_wall_move        ; check if walls are blocking movement in DE
                call    check_doorway        ; check if player is standing in a doorway
                call    chk_decor_move       ; check if decor is blocking movement in DE
                jp      apply_move           ; apply movement in DE

; serf character handler
h_serf:
                ld      bc, &2020            ; walk deceleration
                ld      de, &0101             ; walk acceleration
                ld      hl, &0707             ; unused
                call    control_player       ; read controls and apply player movement
                ld      e, (ix+6)            ; x velocity
                ld      d, (ix+7)            ; y velocity
                ld      a, d
                or      e                    ; is player moving?
                jr      z, loc_8E0F          ; jump if not
                ld      a, (sysvar_FRAMES)
                and     3                    ; 1/4 update rate
                jr      nz, loc_8E0F         ; jump if not time
                ld      a, (ix+0)
                and     3                    ; keep animation frame bits
                add     a, &21               ; add base serf graphic
                ld      (ix+0), a
                ld      a, d
                and     a                    ; moving down?
                jp      p, loc_8DF2          ; jump if so
                neg                          ; abs
loc_8DF2:
                ld      c, a
                ld      a, e
                and     a                    ; moving right?
                jp      p, loc_8DFA          ; jump if so
                neg                          ; abs
loc_8DFA:
                cp      c                    ; moving more up/down than left/right?
                jr      nc, loc_8E1A         ; jump if so
                ld      a, d
                and     a                    ; moving up?
                ld      a, (ix+0)
                jp      m, loc_8E07          ; jump if so
                add     a, 4                 ; offset to down sprites
loc_8E07:
                add     a, 8                 ; offset to right sprites
loc_8E09:
                ld      (ix+0), a
                call    walk_sound           ; play walk clicks if due
loc_8E0F:
                call    read_controls        ; return controls in A (FUDLR order, negative logic)
                and     &10                  ; fire pressed?
                call    z, serf_fire         ; call if so (fire weapon)
                jp      loc_8E78
loc_8E1A:
                ld      a, e
                and     a                    ; moving left?
                ld      a, (ix+0)
                jp      m, loc_8E09          ; jump if so
                add     a, 4                 ; offset to right sprites
                jr      loc_8E09

; knight character handler
h_knight:
                ld      bc, &2020            ; walk deceleration
                ld      de, &0303             ; walk acceleration
                ld      hl, &0707             ; unused
                call    control_player       ; read controls and apply player movement
                ld      e, (ix+6)            ; current x velocity
                ld      d, (ix+7)            ; current y velocity
                ld      a, d
                or      e                    ; player moving?
                jr      z, loc_8E70          ; jump if not
                ld      a, (sysvar_FRAMES)
                and     3                    ; 1/4 update rate
                jr      nz, loc_8E70         ; jump if not time
                ld      a, (ix+0)
                and     3                    ; keep animation frame bits
                inc     a                    ; add base knight graphic
                ld      (ix+0), a
                ld      a, d
                and     a                    ; moving down?
                jp      p, loc_8E53          ; jump if so
                neg                          ; abs
loc_8E53:
                ld      c, a
                ld      a, e
                and     a                    ; moving right?
                jp      p, loc_8E5B          ; jump if so
                neg                          ; abs
loc_8E5B:
                cp      c                    ; moving more up/down than left/right?
                jr      nc, loc_8E94         ; jump if so
                ld      a, d
                and     a                    ; moving up?
                ld      a, (ix+0)
                jp      m, loc_8E68          ; jump if so
                add     a, 4                 ; offset to down sprites
loc_8E68:
                add     a, 8                 ; offset to right sprites
loc_8E6A:
                ld      (ix+0), a
                call    walk_sound           ; play walk clicks if due
loc_8E70:
                call    read_controls        ; return controls in A (FUDLR order, negative logic)
                and     &10                  ; fire pressed?
                call    z, knight_fire       ; call if so (fire weapon)
loc_8E78:
                call    chk_creatures        ; check whether to add new room creatures
                ld      a, (counter_low)
                and     &0f                  ; 16th game loop?
                jr      nz, loc_8E8E         ; jump if not
                ld      a, (player_energy)
                dec     a                    ; reduce health by 1
                jr      z, player_dead
                ld      (player_energy), a
                call    draw_chicken         ; draw chicken energy bar
loc_8E8E:
                call    draw_entity_disp     ; draw entity to display (no attrs)
                jp      set_entity_attrs2    ; set attrs covering previous and new position
loc_8E94:
                ld      a, e
                and     a                    ; moving left?
                ld      a, (ix+0)
                jp      m, loc_8E6A          ; jump if so (use left sprites)
                add     a, 4                 ; offset to down sprites
                jr      loc_8E6A
player_dead:
                ld      a, (lives)
                and     a                    ; no lives left?
                jp      z, game_over         ; jump if so
                dec     a                    ; lose a life
                ld      (lives), a
                ld      a, (ix+0)
                dec     a
                cp      &30                  ; is player active?
                jr      c, loc_8EC6          ; jump if so
                ld      a, (player)
loc_8EB6:
                ld      (player_steps_y), a
                call    get_sprite_addr      ; return address of sprite A in DE
                ld      a, (de)
                ld      (player_steps_x), a
                ld      a, &67               ; blank graphic, death handler
                ld      (player), a
                ret
loc_8EC6:
                ld      a, (saved_x)
                ld      (player_x), a
                ld      a, (saved_y)
                ld      (player_y), a
                ld      a, (saved_graphic)
                jr      loc_8EB6

; reduce health by 32
damage_32:
                ld      a, (player_energy)
                sub     &20                  ; lose 32 health
                jr      z, loc_8EE1
                jr      nc, loc_8EE9         ; jump if positive
                xor     a
loc_8EE1:
                ld      (player_energy), a
                call    draw_chicken         ; draw chicken energy bar
                jr      player_dead
loc_8EE9:
                ld      (player_energy), a
                jp      draw_chicken         ; draw chicken energy bar

; apply player movement, including auto-walk
move_player:
                ld      a, (ix+2)
                and     &0f                  ; auto-walk active?
                jr      nz, auto_walk        ; jump if so
                ld      a, e                 ; x acceleration
                add     a, (ix+6)            ; add x velocity
                jp      m, loc_8F21          ; jump if moving left
                cp      l                    ; max x velocity?
                jr      c, loc_8F01          ; jump if not
                ld      a, l                 ; limit velocity to max
loc_8F01:
                ld      (ix+6), a            ; update x velocity
                ld      a, d                 ; y acceleration
                add     a, (ix+7)            ; add y velocity
                jp      m, loc_8F2B          ; jump if moving up
                cp      h                    ; max y velocity?
                jr      c, loc_8F0F          ; jump if not
                ld      a, h                 ; limit velocity to max
loc_8F0F:
                ld      (ix+7), a            ; update y velocity
                ld      a, (ix+6)
                call    get_signed_b7_4      ; return signed top nibble
                ld      e, a                 ; x offset
                ld      a, (ix+7)
                call    get_signed_b7_4      ; return signed top nibble
                ld      d, a                 ; y move offset
                ret
loc_8F21:
                neg                          ; abs
                cp      l                    ; max x velocity?
                jr      c, loc_8F27          ; jump if not
                ld      a, l                 ; limit velocity to max
loc_8F27:
                neg                          ; re-negate
                jr      loc_8F01
loc_8F2B:
                neg                          ; abs
                cp      h                    ; max y velocity?
                jr      c, loc_8F31          ; jump if not
                ld      a, h                 ; limit velocity to max
loc_8F31:
                neg                          ; re-negate
                jr      loc_8F0F
auto_walk:
                ld      a, (ix+6)            ; x velocity
                and     a                    ; x movement?
                jp      m, loc_8F52          ; jump if left
                and     &f0                 ; any non-fractional movement?
                jr      z, loc_8F42          ; jump if not
                ld      a, 2                 ; walk right 2 pixels
loc_8F42:
                ld      e, a                 ; x walk in e
                ld      a, (ix+7)
                and     a                    ; auto-walk up/down?
                jp      m, loc_8F5C          ; jump if up
                and     &f0                 ; any non-fractional movement?
                jr      z, loc_8F50          ; jump if not
                ld      a, 2                 ; walk down 2 pixels
loc_8F50:
                ld      d, a                 ; y walk in d
                ret
loc_8F52:
                neg                          ; negate for left
                and     &f0                 ; any non-fractional movement?
                jr      z, loc_8F42          ; jump if not
                ld      a, -2                ; walk left 2 pixels
                jr      loc_8F42
loc_8F5C:
                neg                          ; negate for up
                and     &f0                 ; any non-fractional movement?
                jr      z, loc_8F50          ; jump if not
                ld      a, -2                ; walk up 2 pixels
                jr      loc_8F50
apply_move:
                bit     4, (ix+2)            ; x movement allowed?
                jr      nz, loc_8F73         ; jump if not
                ld      a, e                 ; delta x
                add     a, (ix+3)            ; apply x movement
                ld      (ix+3), a
loc_8F73:
                bit     5, (ix+2)            ; y movement allowed?
                ret     nz                   ; return if not
                ld      a, d                 ; delta y
                add     a, (ix+4)            ; apply y movement
                ld      (ix+4), a
                ret

; return signed top nibble
get_signed_b7_4:
                and     a                    ; positive?
                jp      p, loc_8F8F          ; jump if so
                neg                          ; negate
                rrca
                rrca
                rrca
                rrca                         ; high nibble to low nibble
                and     &0f                  ; keep low nibble
                neg                          ; re-negate
                ret
loc_8F8F:
                rrca
                rrca
                rrca
                rrca                         ; high nibble to low nibble
                and     &0f                  ; keep low nibble
                ret

; decelerate player movement
slow_player:
                ld      a, (ix+2)
                and     &0f                  ; is auto-walk active?
                ret     nz                   ; return if so
                ld      a, (ix+6)
                and     a                    ; x movement?
                jr      z, loc_8FAD          ; jump if not
                jp      m, loc_8FBE          ; jump if left
                sub     l                    ; decelerate
                jp      p, loc_8FAA          ; jump if still positive
stop_x:
                xor     a                    ; stopped on x axis
loc_8FAA:
                ld      (ix+6), a            ; update x velocity
loc_8FAD:
                ld      a, (ix+7)
                and     a                    ; y movement?
                ret     z                    ; return if not
                jp      m, loc_8FC4          ; jump if moving up
                sub     h                    ; decelerate
                jp      p, loc_8FBA          ; jump if still positive
stop_y:
                xor     a                    ; clear auto-walk up/down
loc_8FBA:
                ld      (ix+7), a            ; update y velocity
                ret
loc_8FBE:
                add     a, l                 ; decelerate
                jp      m, loc_8FAA          ; jump if still negative
                jr      stop_x               ; stopped on x axis
loc_8FC4:
                add     a, h                 ; decelerate
                jp      m, loc_8FBA          ; jump if negative
                jr      stop_y               ; stopped on y axis

; check if walls are blocking movement in DE
chk_wall_move:
                push    de
                ld      a, e
                add     a, (ix+3)            ; apply x movement
                ld      e, a
                ld      d, (ix+4)            ; apply y movement
                ld      b, &10               ; x bit mask
                call    chk_walls            ; check if position is within room interior
                pop     de
                push    de
                ld      e, (ix+3)
                ld      a, d
                add     a, (ix+4)
                ld      d, a
                ld      b, &20
                call    chk_walls            ; check if position is within room interior
                pop     de
                ret

; check if position is within room interior
chk_walls:
                ld      hl, room_width
                ld      a, e                 ; player x
                sub     &58                  ; subtract room centre x
                jp      p, loc_8FF4
                neg                          ; abs
loc_8FF4:
                cp      (hl)                 ; within room width?
                ret     nc                   ; return if so
                inc     hl
                ld      a, d                 ; player y
                sub     &68                  ; subtract room centre y
                jp      p, loc_8FFF
                neg                          ; abs
loc_8FFF:
                cp      (hl)                 ; within room height?
                ret     nc                   ; return if so
                ld      a, b
                cpl
                and     (ix+2)               ; clear bit in B
                ld      (ix+2), a
                ret

; check if decor is blocking movement in DE
chk_decor_move:
                push    de
                ld      a, e
                add     a, (ix+3)
                ld      e, a
                ld      d, (ix+4)
                ld      a, &10               ; bit for x movement allowed
                ex      af, af'
                call    chk_decor            ; check if room decor is blocking movement
                pop     de
                push    de
                ld      e, (ix+3)
                ld      a, d
                add     a, (ix+4)
                ld      d, a
                ld      a, &20               ; bit for y movement allowed
                ex      af, af'
                call    chk_decor            ; check if room decor is blocking movement
                pop     de
                ret

; check if room decor is blocking movement
chk_decor:
                ld      c, (ix+1)
                ld      b, 0
                ld      hl, room_table
                sla     c
                rl      b                    ; * 2 (bytes per entry)
                add     hl, bc
                ld      c, (hl)
                inc     hl
                ld      b, (hl)
loc_903B:
                ld      a, (bc)              ; room item LSB
                inc     bc
                ld      l, a
                ld      a, (bc)              ; room item MSB
                inc     bc
                ld      h, a
                or      l
                ret     z
                push    bc
                ld      bc, room_table
                and     a
                sbc     hl, bc
                inc     hl
                ld      a, (hl)
                cp      (ix+1)               ; in player room?
                jr      z, loc_9055          ; jump if so
                ld      bc, 8                ; 8 bytes per entry
                add     hl, bc               ; next (linked) entry
loc_9055:
                inc     hl
                inc     hl
                ld      c, (hl)              ; x
                inc     hl
                ld      b, (hl)              ; y
                inc     hl
                ld      a, (hl)              ; flags
                inc     hl
                bit     2, a
                jr      nz, loc_909B
                bit     3, a
                jr      nz, loc_9098
                ld      a, (hl)
                sra     a
                sra     a
                and     &fc
                add     a, c
                sub     e
                neg
                ld      c, a
                ld      a, (hl)
                rlca
                rlca
                and     &3c
                inc     hl
                cp      c
                jr      c, loc_9098
                ld      a, (hl)
                sra     a
                sra     a
                and     &fc
                add     a, b
                sub     d
                ld      b, a
                ld      a, (hl)
                inc     hl
                rlca
                rlca
                and     &3c
                cp      b
                jr      c, loc_9098
                ex      af, af'
                ld      c, a
                ex      af, af'
                ld      a, c
                cpl
                and     (ix+2)               ; disallow movement bit
loc_9095:
                ld      (ix+2), a
loc_9098:
                pop     bc
                jr      loc_903B
loc_909B:
                ld      a, (hl)
                sra     a
                sra     a
                and     &fc
                add     a, c
                sub     e
                neg
                ld      c, a
                ld      a, (hl)
                rlca
                rlca
                and     &3c
                inc     hl
                cp      c
                jr      c, loc_9098
                ld      a, (hl)
                sra     a
                sra     a
                and     &fc
                add     a, b
                sub     d
                ld      b, a
                ld      a, (hl)
                inc     hl
                rlca
                rlca
                and     &3c
                cp      b
                jr      c, loc_9098
                ex      af, af'
                ld      c, a
                ex      af, af'
                ld      a, c
                or      (ix+2)               ; allow movement bit
                jr      loc_9095

; check if player has left through a door
check_exit:
                ld      a, (player_contact)
                and     &0f                  ; touching enemy?
                ret     nz                   ; return if so [check]
                ld      a, (player)
                dec     a
                cp      &30                  ; player active?
                ret     nc                   ; return if not
                bit     6, (ix+5)            ; top/bottom door?
                jr      z, loc_90E1          ; jump if so
                srl     c                    ; halve vertical distance
loc_90E1:
                ld      a, (player_x)
                sub     (ix+3)               ; x distance
                cp      c                    ; within range?
                ret     nc                   ; return if not
                bit     6, (ix+5)            ; left/right door?
                jr      nz, loc_90F1         ; jump if so
                srl     b                    ; halve horiztonal distance
loc_90F1:
                ld      a, (player_y)
                sub     (ix+4)               ; y distance to exit
                neg
                cp      b                    ; within range?
                ret                          ; return no-carry if not

; check if player is touching entity
check_touching:
                ld      a, (player_x)
                sub     (ix+3)               ; x distance
                jp      p, loc_9106
                neg                          ; abs
loc_9106:
                cp      &0c                  ; within range?
                ret     nc                   ; return if not
                ld      a, (player_y)
                sub     (ix+4)               ; y distance
                jp      p, loc_9114
                neg                          ; abs
loc_9114:
                cp      &0c                  ; within range?
                ret                          ; return no-carry if not

; move player to room linked to entity (usually door)
change_room:
                call    get_linked_door      ; get connected door exit
                ld      a, (ix+1)
                ld      (player_room), a     ; move player to connected room
                ld      a, (ix+2)            ; bits 3-0 used for x offset
                rlca                         ; * 2
                and     &1e
                add     a, (ix+3)            ; add x
                ld      (player_x), a        ; set player x to exit
                ld      a, (ix+2)            ; bits 7-4 used for y offset
                rrca
                rrca
                rrca                         ; * 2 (effectively)
                and     &1e
                neg                          ; invert
                add     a, (ix+4)            ; add y
                ld      (player_y), a        ; set player y to exit
                call    set_entry_walk       ; auto-walk into the room
                ld      a, (player_contact)
                or      &0f
                ld      (player_contact), a
enter_room:
                ld      a, (player_room)
                call    visit_room           ; mark room A as visited
                call    clear_play_area      ; clear screen and attrs of play area
                call    draw_room_frame      ; draw lines that make up outer room frame
                call    draw_panel_attrs     ; draw side-panel colours, which follow room colour
                call    draw_inventory       ; draw any items in player inventory
                call    entry_sound          ; room entry sound effect
                jp      main_loop

; open door handler
h_door_open:
                ld      a, (counter_low)
                and     1                    ; 2 alternating tasks
                jp      nz, h_door_exit      ; jump if we're checking exits this time
                ld      a, (door_timer)
                and     a                    ; door timer expired?
                jr      z, loc_9174          ; jump if so
                dec     a                    ; reduce timer
                ld      (door_timer), a
                jp      h_door_exit          ; jump to check exits
loc_9174:
                ld      a, (in_doorway)
                and     a                    ; player standing in doorway?
                jp      nz, h_door_exit      ; jump if so (run exit logic only)
                jr      loc_9193
h_door_closed:
                ld      a, (counter_low)     ; closed door handler
                and     1                    ; 2 alternating tasks
                jp      nz, h_room_item      ; jump if we're drawing this time
                ld      a, (door_timer)
                and     a                    ; door timer expired?
                jp      z, loc_9193          ; jump if so
                dec     a
                ld      (door_timer), a
                jp      h_room_item          ; draw room item
loc_9193:
                ld      a, &5e               ; 0x5E * 2 / 50 = 3.76 seconds, due to halved timer processing
                ld      (door_timer), a
                ld      a, (ix+5)            ; save door attr
                push    af
                or      3
                ld      (ix+5), a
                call    draw_rot_obj         ; undraw door
                ld      a, (ix+0)            ; entity type
                xor     1                    ; toggle open/close state
                call    set_door_type        ; set door type for both linked entities
                call    draw_rot_obj         ; redraw door
                pop     af
                ld      (ix+5), a            ; restore door attr
                call    update_door          ; update solid/passable door state
                call    h_room_item          ; draw room item
                jp      door_sound           ; door sound (short burst of white noise)

; closed trapdoor handler
h_trap_closed:
                ld      a, (counter_low)
                and     a
                jp      nz, h_room_item      ; draw room item
                jr      trap_common
h_trap_open:
                ld      a, (rand8)           ; open trapdoor handler
                and     a                    ; zero?
                jp      nz, chk_trap_exit    ; jump if not
trap_common:
                ld      a, (ix+5)
                push    af
                or      3
                ld      (ix+5), a
                call    draw_rot_obj
                ld      a, (ix+0)
                xor     1                    ; toggle open/closed state
                ld      (ix+0), a
                call    draw_rot_obj
                pop     af
                ld      (ix+5), a
                call    h_room_item          ; draw room item
                jp      door_sound           ; door sound (short burst of white noise)

; big door exit handler
h_big_door_exit:
                ld      bc, &2020            ; 32x32 size
                jr      loc_91F5

; door exit handler
h_door_exit:
                ld      bc, &1111            ; 17x17 exit size
loc_91F5:
                call    check_exit           ; check if player has left through a door
                call    c, change_room       ; move player to room linked to entity (usually door)
                jp      h_room_item          ; draw room item

; draw room item
h_room_item:
                ld      e, (ix+3)            ; xpos
                ld      d, (ix+4)            ; ypos
                dec     d
                ld      c, (ix+0)            ; graphic
                ld      b, (ix+5)            ; attr
                call    draw_bc_at_de        ; B=attr, C=graphic, E=xpos, D=ypos
                ld      a, (game_flags)      ; b0 set if room content drawn
                and     a                    ; room content drawn?
                ret     nz                   ; return if so

draw_rot_obj:
                ld      e, (ix+3)            ; xpos
                ld      d, (ix+4)            ; ypos
                ld      c, (ix+0)            ; graphic index
                ld      b, (ix+5)            ; orientation
                jp      draw_orientation

; return if player has required key (C if opened, NC if locked)
check_key_colour:
                                             
                ld      a, (mod_selection)   ; LOGIC: IF MOD SELECTED BYPASS_KEY_CHK
                and     3
                cp      2                    ; mod option 2 selected?
                jp z,   bypass_key_chk       ; jump if so
                ld      a, (ix+0)
                and     3                    ; locked door colour index
                ld      hl, key_attrs
                call    add_hl_a             ; HL = HL + A
                ld      d, (hl)              ; key colour attr
                ld      e, &81               ; key graphic
                call    check_carrying       ; is player carrying the required key colour?
                jp      nz, loc_923F         ; jump if not
bypass_key_chk  call    enter_door           ; enter linked object (door etc.)
                ld      bc, &1111            ; 17x17 size
                jp      check_exit           ; check if player has left through a door
loc_923F:
                call    loc_9565
                and     a                    ; door locked
                ret

; coloured locked door handler
h_door_locked:
                call    check_key_colour     ; does player have the required key colour?
                jp      nc, h_room_item      ; jump if not
                ld      a, 2                 ; open door graphic
loc_924C:
                call    set_door_type        ; set door type for both linked entities
                jp      change_room          ; move player to room linked to entity (usually door)

; coloured cave locked door handler
h_cave_locked:
                call    check_key_colour     ; return if player has required key (C if opened, NC if locked)
                jp      nc, h_room_item      ; draw room item
                ld      a, 1                 ; open cave graphic
                jr      loc_924C

key_attrs:      db  &42                       ; red
                db  &44                       ; green
                db  &45                       ; cyan
                db  &46                       ; yellow

; set door type for both linked entities
set_door_type:
                push    ix
                pop     hl
                ld      (hl), a              ; set door graphic
                ex      af, af'
                ld      a, l
                xor     8                    ; linked entry
                ld      l, a
                ex      af, af'
                ld      (hl), a              ; set linked door graphic
                ret

; HL = HL + A
add_hl_a:
                add     a, l
                ld      l, a
                ld      a, h
                adc     a, 0
                ld      h, a
                ret

; check if player is carrying object E with colour D
check_carrying:
                ld      b, 3                 ; 3 inventory slots to search
                ld      hl,  inventory1+2
loc_9278:
                ld      a, (hl)              ; item colour
                cp      e                    ; match?
                inc     hl
                jr      nz, loc_9280         ; jump if not
                ld      a, (hl)              ; item graphic
                cp      d                    ; match?
                ret     z                    ; return if so
loc_9280:
                inc     hl
                inc     hl
                inc     hl                   ; next inventory slot
                djnz    loc_9278
                ret

; get connected door exit
get_linked_door:
                push    ix
                pop     hl
                ld      a, l
                xor     8                    ; swap 8-byte entry
                ld      l, a
                push    hl
                pop     ix
                ret

; draw all non-monster entities in the current room
draw_entities:
                ld      ix, player
loc_9295:
                ld      a, (ix+0)
                and     a                    ; slot used?
                jr      z, loc_92A6          ; jump if not
                ld      a, (player_room)
                cp      (ix+1)               ; in player room?
                jr      nz, loc_92A6         ; jump if not
                call    draw_entity          ; draw entity graphic (no attrs)
loc_92A6:
                ld      de, 8                ; 8 bytes per entry
                add     ix, de
                push    ix
                pop     hl
                ld      de, creature1        ; end marker
                and     a
                sbc     hl, de               ; more 8-byte entries to process?
                jr      c, loc_9295          ; jump back if so
loc_92B6:
                ld      a, (ix+0)
                and     a                    ; slot used?
                jr      z, loc_92C7          ; jump if not
                ld      a, (player_room)
                cp      (ix+1)               ; in player room?
                jr      nz, loc_92C7         ; jump if not
                call    draw_entity          ; draw entity graphic (no attrs)
loc_92C7:
                ld      de, &10              ; 16 bytes per entry
                add     ix, de
                push    ix
                pop     hl
                ld      de, linked_items     ; end of 16-byte entities
                and     a
                sbc     hl, de               ; more 16-byte entries to draw?
                jr      c, loc_92B6          ; jump back if so
                ret

; clear pickup key flag
;pickup_released:
;                ld      a, (pickup_flags)
;               and     &fd                 ; clear b1 (pickup key not pressed)
;               ld      (pickup_flags), a
draw_16x16:
                ld      a, &10               ; 16 lines high by default

; set spawn appearance width/height
set_appear_w_h:
                ld      (height_lines), a
                ld      a, (ix+3)
                and     7                    ; x aligned on cell boundary?
                ld      a, 2                 ; 2 bytes wide
                jr      z, loc_92EF
                inc     a                    ; extra byte needed
loc_92EF:
                ld      (width_bytes), a
                jp      set_entity_attrs2    ; set attrs covering previous and new position

; pickup item handler

acg_key_flag:   db      0
pickup_timer:   db      0
auto_pickup_flag: equ   1

h_pickup_item:
                call    save_entity         ; Save for undraw

                ; --- 1. THE PICKUP TIMER (The Buffer) ---
                ld      a, (pickup_timer)
                and     a                   ; Is timer at zero?
                jr      z, .check_handled   ; If zero, proceed to pickup logic.

                ; --- TIMER ACTIVE: COUNT DOWN ---
                dec     a                   ; Subtract 1 from timer
                ld      (pickup_timer), a
                jp      draw_16x16          ; Skip pickup this frame

.check_handled:
                ; --- 2. THE HANDLED CHECK ---
                ld      a, (pickup_flags)
                bit     1, a                ; Is an action already handled?
                jr      nz, pickup_released ; Skip to release logic

                ; --- 3. AUTO / MANUAL TOGGLE ---

                ld      a, (mod_selection)   ; LOGIC: IF MOD NOT SELECTED JUMP TO MANUAL LOGIC
                and     8
                jp      z,   man_logic       ; 

                ;ld      a, (auto_pickup_flag)
                ;and     a
                ;jr      z, man_logic

auto_logic:
                ; --- 4A. AUTO PICKUP LOGIC ---
                ld      a, (player)
                dec     a
                cp      &30                 ; Active?
                jr      nc, draw_16x16
                call    check_touching      ; Touching?
                jr      nc, draw_16x16
                jr      item_id_check       ; Success: Go to ID check

man_logic:      
                ; --- 4B. MANUAL PICKUP LOGIC ---
                ld      a, (pickup_pressed)
                and     a                   ; Key pressed?
                jr      z, pickup_released
                call    check_touching      ; Touching?
                jr      nc, draw_16x16




                ;MOD - ACG key part picked up? (LATER RENAMED STEP 4)
                ; ---------------------------------- 
item_id_check:  ld      a, (ix+0)            ; Get item ID from entity buffer
                cp      &8c                  ; Is it < &8C (part 1)?
                jr      c, update_inv        ; If not, jump
                cp      &8f                  ; Is it > 8F (part 3+1)?
                jr      nc, update_inv       ; If so, jump

                ; A is currently &8C, &8D, or &8E
                sub     &8c                  ; Normalize to 0, 1, or 2
                ld      hl, acg_key_flag
                ld      b, a                ; Store normalized ID (0, 1, or 2) in B
                ld      a, 1                ; Start with bit 0 (value 1)
                jr      z, update_acg_flag  ; If it was 0, we are done shifting
acg_flag_loop:
                add     a, a                ; Shift left (effectively bit 1, then bit 2)
                djnz    acg_flag_loop
update_acg_flag:
                or      (hl)                ; Combine new bit with existing flags
                ld      (hl), a             ; Save it back!
                call    inventory_sound

                
                ld      a, (pickup_flags)
                or      %00000010           ; Set Bit 1 (Signifies "Handled")
                ld      (pickup_flags), a

                ; --- The "Fake" Inventory Pickup ---
                ; We do the cleanup that add_inventory usually does, 
                ; but we DON'T update the inventory1-3 buffers.
                
                call    undraw_entity        ; Erase the key's pixels from the screen
                
                ld      a, (room_attr)       ; Get current room's background color
                ld      (ix+5), a            ; Set the entity's attribute to "background"
                call    set_entity_attrs2    ; Update attribute memory (removes the "ink")

                call    draw_panel_attrs     ; Refresh side panel (Turns Blue to Yellow)
                call    draw_inventory

                ld      (ix+0), 0            ; *** IMPORTANT: Deactivate item in room buffer
                                             ; This stops the player from "re-touching" it.
                                
                ret                          
                ; ---------------------------------- 

update_inv:     
                call add_history

                ; --- 1. WIND UP THE AMNESIA TIMER ---
                ; This gives us ~0.2s to move away from the dropped item
                ld      a, 10
                ld      (pickup_timer), a

                ; --- 2. SET THE HANDLED LATCH ---
                ; We only set Bit 1 now. Bit 0 is handled by the timer.
                ld      a, (pickup_flags)
                or      %00000010           ; Set "Handled" (Bit 1)
                ld      (pickup_flags), a

                ; --- 3. THE TRANSACTION ---
                call    drop_item           ; Drop Slot 3 to the floor
                call    shift_inventory     ; Move Slot 1+2 -> Slot 2+3
                call    add_inventory       ; Put NEW item into Slot 1
                
                jp      draw_inventory      ; Side panel refresh & Exit

                ; --- PART 3: THE RESET (NEW) ---
pickup_released:
                ; --- 7. RELEASE LOGIC ---
                ld      a, (pickup_pressed)
                and     a
                jr      nz, .skip_reset     ; Still holding key? Stay latched.

                call    check_touching
                jr      c, .skip_reset      ; Still touching item? Stay latched.

                ld      a, (pickup_flags)
                res     1, a                ; Safe to clear "Handled" bit
                ld      (pickup_flags), a

.skip_reset:
                jp      draw_16x16

; add item to inventory slot 1
add_inventory:
                ld      hl, inventory1
                push    ix
                pop     de
                ld      (hl), e              ; entity LSB
                inc     hl
                ld      (hl), d              ; entity MSB
                inc     hl
                ld      a, (ix+0)
                ld      (hl), a              ; graphic
                inc     hl
                ld      a, (ix+5)
                ld      (hl), a
                call    undraw_entity
                ld      a, (room_attr)
                ld      (ix+5), a
                call    set_entity_attrs2    ; set attrs covering previous and new position
                ld      (ix+0), 0
                jp      inventory_sound

; move items 1+2 to slots 2+3
shift_inventory:
                ld      hl,  inventory2+3
                ld      de,  inventory3+3
                ld      bc, 8                ; 2 items * 4 bytes
                lddr                         ; shift up items
                ret

; drop last item in inventory
drop_item:
                ld      hl, inventory3
                ld      e, (hl)
                inc     hl
                ld      d, (hl)
                inc     hl
                ld      a, d
                or      e
                ret     z                    ; return if no item to drop
                push    de
                ld      a, (hl)              ; graphic idx
                inc     hl
                ld      (de), a
                inc     de
                ld      a, (player_room)
                ld      (de), a              ; set item room
                inc     de
                ld      a, &80
                ld      (de), a
                inc     de
                ld      a, (player_x)
                ld      (de), a              ; set item xpos
                inc     de
                ld      a, (player_y)
                ld      (de), a              ; set item ypos
                inc     de
                ld      a, (hl)              ; inventory colour
                ld      (de), a              ; set item attr
                pop     de
                call    drop_sound
                push    ix
                push    de
                pop     ix
                call    draw_entity          ; draw entity graphic (no attrs)
                pop     ix
                ret

; check whether pick-up key has been pressed
check_pickup_key:
                ld      a, &7e               ; read V/C/X/Z/Shift and B/N/M/Sym/Space rows
                out     (&fd), a
                in      a, (&fe)
                cpl
                and     2                    ; non-zero if Symbol Shift or Z pressed
                ld      (pickup_pressed), a
                ret
read_cursor:
                ld      a, &ef
                out     (&fd), a
                in      a, (&fe)            ; xxx67890
                ld      c, a
                and     8                    ; 7 key
                ld      e, a
                ld      a, c
                rrca                         ; 0xxx6789
                rrca                         ; 90xxx678
                and     &45                  ; ?+6+8 keys
                or      e
                ld      e, a
                rrca                         ; 890xxx67
                rrca                         ; 7890xxx6
                and     &10                  ; 0 key
                or      e
                and     &1f
                ld      e, a
                ld      a, &f7              ; xxx54321
                out     (&fd), a
                in      a, (&fe)
                rra                          ; 1xxx5432
                rra                          ; 21xxx543
                rra                          ; 321xxx54
                and     2                    ; 5 key
                or      e
                ret

; return controls in A (FUDLR order, negative logic)
read_controls:
                ld      a, (main_selection)
                and     6
                jr      z, read_keyboard
                cp      4
                jr      z, read_cursor
                in      a, (&1f)             ; read Kempston joystick
                cpl
                ret
read_keyboard:
                ld      a, &fb
                out     (&fd), a
                in      a, (&fe)            ; xxxTREWQ
                ld      c, a
                rra
                and     1                    ; W key
                ld      e, a
                ld      a, c
                rla
                and     2                    ; Q key
                or      e
                ld      e, a
                ld      a, c
                and     &1c                  ; ___TRE__
                or      e                    ; ___TREQW
                ret

h_blank:
                ; --- 1. PLAYER STATUS CHECK ---
                ld      a, (player)
                dec     a
                cp      &30                 ; Is player active?
                ret     nc                  ; Return if not

                ; --- 2. INPUT DETECTION ---
                ld      a, (pickup_pressed)
                and     a                   ; Is the pick-up key NOT pressed?
                jr      z, .key_released    ; If NOT pressed, go to reset

                ; --- 3. DROP HANDLED CHECK ---
                ld      a, (pickup_flags)
                bit     1, a                ; Check Bit 1: Is "Drop Handled"?
                ret     nz                  ; YES: Already dropped this press. Stop.

                ; --- 4. EXECUTE MANUAL DROP ---
                ; Set the Pickup Timer to 10 frames (~0.2 seconds)
                ld      a, 10
                ld      (pickup_timer), a

                ld      a, (pickup_flags)
                or      %00000010           ; Set Bit 1: Mark as "Drop Handled"
                ld      (pickup_flags), a

                call    drop_item           
                call    shift_inventory     
                
                ld      hl, 0               ; Clear Slot 1
                ld      (inventory1), hl
                ld      (inventory1+2), hl
                
                call    draw_inventory      
                ret

.key_released:
                ; --- 5. THE RESET ---
                ld      a, (pickup_flags)
                res     1, a                ; Clear "Drop Handled" only
                ld      (pickup_flags), a
                ret
                
h_barrel:
                ld      a, (mod_selection)      ; LOGIC: IF MOD SELECTED BYPASS_CHAR_CHK
                and     3
                cp      2
                jp z,   bypass_char_chk
                ld      a, (player)
                sub     &21                  ; subtract serf base graphic
                jr      loc_9433
h_bookcase:
                ld      a, (mod_selection)      ; LOGIC: IF MOD SELECTED BYPASS_CHAR_CHK
                and     3
                cp      2
                jp z,   bypass_char_chk
                ld      a, (player)
                sub     &11                  ; subtract wizard base graphic
                jr      loc_9433
h_clock:
                ld      a, (mod_selection)      ; LOGIC: IF MOD SELECTED BYPASS_CHAR_CHK
                and     3
                cp      2
                jp z,   bypass_char_chk
                ld      a, (player)
                dec     a                    ; subtract knight base graphic
loc_9433:
                cp      &10                  ; required player type to pass through?
                jr      nc, loc_943D         ; jump if not
bypass_char_chk call    enter_door           ; enter linked object (door etc.)
                jp      h_door_exit          ; door exit handler
loc_943D:
                call    loc_9565
                jp      h_room_item          ; draw room item

; prepare player to spawn
prepare_player:
                ld      a, (main_selection)
                rlca
                and     &30                  ; base character graphic
                add     a, 8                 ; offset to desired facing direction
                ld      (player_template+7), a ; set spawn graphic
                ld      a, (player_room)     ; current player room
                ld      (player_template+1), a ; respawn in same room
                ld      hl, player_template
                ld      de, player
                ld      bc, 8                ; player entity size
                ldir                         ; copy to live player
                ld      a, &68               ; flash score for 104 frames
                ld      (flash_timer), a     ; score flash timer
                ld      a, (lives)
                cp      3                    ; first game spawn? (full lives)
                jr      z, loc_9476          ; jump if so (skip drawing player)
                push    ix
                ld      ix, player
                call    draw_entity          ; draw entity graphic (no attrs)
                pop     ix
loc_9476:
                ld      a, &f0              ; starting energy
                ld      (player_energy), a
                call    draw_chicken         ; draw chicken energy bar
                jp      draw_lives           ; draw lives sprites in side panel

player_template:db  &66, 0, 0, &60, &68, &47, &ff, 0 ; blank graphic and h_player_appear handler

; check for pause key, return when not paused
check_pause:
                di                           ; disable interrupts to suspend FRAMES counter advance
                ld      a, &7e
                out     (&fd), a
                in      a, (&fe)
                bit     0, a                 ; pause (space/shift) pressed?
                ret     nz                   ; return if not
                cpl
                and     &1e                  ; any other key on the same row pressed?
                ret     nz                   ; return if so
loc_9497:
                ld      a, &7e
                out     (&fd), a
                in      a, (&fe)
                bit     0, a                 ; space/shift pressed?
                jr      z, loc_9497          ; jump if so (wait until released)
loc_94A1:
                ld      a, &7e
                out     (&fd), a
                in      a, (&fe)
                bit     0, a                 ; space/shift pressed?
                jr      nz, loc_94A1         ; jump if not (main pause loop)
loc_94AB:
                ld      a, &7e
                out     (&fd), a
                in      a, (&fe)
                bit     0, a                 ; space/shift pressed?
                jr      z, loc_94AB          ; jump if so (wait until pause key released)
                ret

; set locations of ACG key pieces
place_key_pieces:
                ld      a, (sysvar_FRAMES)
                ld      c, a
                ld      a, (counter_low)
                add     a, c
                and     7
                ld      c, a
                add     a, a                 ; * 2
                add     a, c                 ; * 3 (3 key pieces per entry)
                
                ; --- APPLY OFFSET MOD HERE ---
                ld      c, a                 ; Temporarily save our index (0-21)
                ld      a, (mod_selection)
                and     %00000100            ; Check Bit 2
                jr      z, no_offset
                ld      a, 24                ; If Bit 2 set, add 24 to skip to next table block
                add     a, c
                jr      final_index
no_offset:      ld      a, c
final_index:    ; --- END MOD ---

                ld      l, a
                ld      h, 0
                ld      bc, acg_key_rooms
                add     hl, bc
                ex      de, hl
                ld      hl,  acg_key_init+1  ; first key piece room
                ld      bc, 8                ; 8 bytes per entity
                ld      a, 3                 ; 3 key pieces
loc_94D3:
                ex      af, af'
                ld      a, (de)
                ld      (hl), a
                add     hl, bc
                inc     de
                ex      af, af'
                dec     a
                jr      nz, loc_94D3
                ret

acg_key_rooms:  db  &81, &45, &7c
                db  &85, &49, &2b
                db  &6a, &3b, &7c
                db  &69, &71, &2b
                db  &67, &85, &7c
                db  &68, &7f, &2b
                db  &4d, &73, &7c
                db  &17, &10, &2b
 gf_acg_keys:   db  &73, &17, &70
                db  &04, &08, &6c
                db  &01, &6F, &10
                db  &07, &6c, &70
                db  &19, &14, &09
                db  &6b, &01, &16
                db  &0d, &14, &08
                db  &14, &0c, &6e

; randomise which doors can open/close
randomise_doors:
                ld      a, (counter_low)
                ld      l, a                 ; set ROM addr LSB
                ld      a, (sysvar_FRAMES)   ; 0-49
                and     &0f                  ; limit to 4K (0000-0FFF)
                or      &10                  ; add 4K (1000-1FFF)
                ld      h, a                 ; set ROM addr MSB
                exx
                ld      hl, linked_items     ; pairs of linked items, including doors
                ld      de,  linked_items+8  ; pairs of linked items, including doors
                ld      bc, &10              ; 16 bytes per entry
loc_950B:
                exx
                ld      a, (hl)              ; read ROM byte
                inc     hl
                exx
                cp      &70                  ; ROM value >= 0x70 (~56% chance)
                jr      nc, loc_951F         ; jump if so (door always open)
                ld      a, (de)
                cp      (hl)                 ; same value?
                jr      nz, loc_951F         ; jump if not (no change)
                cp      1                    ; cave doorway?
                jr      z, loc_9526          ; jump if so
                cp      2                    ; normal doorway?
                jr      z, loc_9542          ; jump if so
loc_951F:
                add     hl, bc               ; next entry
                ex      de, hl
                add     hl, bc               ; next entry
                ret     c                    ; return if hit end of RAM
                ex      de, hl
                jr      loc_950B
loc_9526:
                ld      a, &22               ; mode?
loc_9528:
                ld      (de), a
                ld      (hl), a
                push    de
                inc     de
                inc     de
                inc     de
                inc     de
                inc     de                   ; + 5
                ld      a, (de)
                or      8
                ld      (de), a
                pop     de
                push    hl
                inc     hl
                inc     hl
                inc     hl
                inc     hl
                inc     hl
                ld      a, (hl)
                or      8
                ld      (hl), a
                pop     hl
                jr      loc_951F
loc_9542:
                ld      a, &20               ; mode?
                jr      loc_9528

; update solid/passable door state
update_door:
                ld      a, (ix+0)
                and     1                    ; is door open?
                jr      z, loc_9565          ; jump if so
enter_door:
                ld      a, (ix+5)            ; enter linked object (door etc.)
                and     &f7                 ; object is solid
                ld      (ix+5), a
                push    ix
                call    get_linked_door      ; get connected door exit
                ld      a, (ix+5)
                and     &f7                 ; linked object is solid
                ld      (ix+5), a
                pop     ix
                ret
loc_9565:
                ld      a, (ix+5)
                or      8                    ; object can be passed through
                ld      (ix+5), a
                push    ix
                call    get_linked_door      ; get connected door exit
                ld      a, (ix+5)
                or      8                    ; linked object can be passed through
                ld      (ix+5), a
                pop     ix
                ret

; check if player is standing in a doorway
check_doorway:
                push    de
                ld      b, 0
                ld      hl, (room_width)
                inc     l                    ; increase interior width
                inc     h                    ; increase interior height
                ld      e, (ix+3)            ; player x
                ld      d, (ix+4)            ; player y
                ld      a, e
                sub     &58                  ; subtract room centre x
                jp      p, loc_9593
                neg                          ; abs
loc_9593:
                cp      l                    ; within interior width?
                jr      c, loc_9597          ; jump if so
                inc     b                    ; mark as in left/right doorway
loc_9597:
                ld      a, d
                sub     &68                  ; subtract room centre y
                jp      p, loc_959F
                neg                          ; abs
loc_959F:
                cp      h                    ; within interior height?
                jr      c, loc_95A3          ; jump if so
                inc     b                    ; mark as in top/bottom doorway
loc_95A3:
                ld      a, b
                ld      (in_doorway), a      ; non-zero if in a doorway
                pop     de
                ret
; ---------------------------------------------------------------------------
; mod: hides/restores status of doors relevant to single floor game
; ---------------------------------------------------------------------------

gf_mod:

                ld      a, (mod_selection)
                and     %00000100
                ld      c, a                ; C = offset = 4 (mod selection) or 0 (not selected)
                
                ld      hl, gf_doors
                ld      b, 6                ; B = no of doors to be hidden/restored
gf_loop:
                ld      e, (hl)             ; LSB of door address
                inc     hl
                ld      d, (hl)             ; MSB of door address
                inc     hl
                
                push    de
                pop     ix                  ; IX = DE = Target Object

                ; --- Calculate Pointer to correct data ---
                push    hl                  ; Store HL (position in gf_doors)
                ld      a, l                 
                add     a, c                 
                ld      l, a                ; HL = HL + Offset (HL+4 = B4-B7 in gf_doors)
                jr      nc, gf_transfer     ; NC = No Carry (Same Page)
                inc     h                   ; Carry = Page Boundary Cross
gf_transfer:
                ; --- Unified Data Transfer (3 Bytes) ---
                ld      a, (hl)
                ld (ix+0), a  ; Type
                inc     hl
                ld      a, (hl)
                ld (ix+2), a  ; Gfx
                inc     hl
                ld      a, (hl)
                ld (ix+4), a  ; Y-Coord
                inc     hl
                ld      a, (hl)
                ld (ix+6), a  ; Attribute
                
                pop     hl                  ; Restore HL (position in gf_doors plus offset)
                ld      de, 8               ; 
                add     hl, de              ; HL = next door (8 bytes ahead))
                
                djnz    gf_loop             ; Loop while B <> 0
                ret

gf_doors:
; ---------------------------------------------------------------------------
; dw = door address; db B0-B3 'display' door values; db B4-B7 'hide' door values
; ---------------------------------------------------------------------------
                dw door_1A_06
                db &02, &34, &3f, &04, &25, &00, &38, 0   
                dw door_03_26
                db &02, &34, &97, &04, &25, &00, &97, 0
                dw door_70_71_s
                db &02, &34, &1f, &04, &25, &00, &17, 0
                dw trap_03_65
                db &19, &34, &70, &24, &1b, &34, &74, &24
                dw trap_15_66
                db &19, &34, &80, &24, &1b, &34, &74, &24
                dw trap_73_74
                db &19, &34, &70, &24, &1b, &34, &70, &24


; --- Random Start Room Mod ---

start_room_mod:
                
                ; --- Check if Mod 6 (Bit 4) is active ---
                ld      a, (mod_selection)
                and     16                  ; Mask Bit 4 (%00010000)
                jr      z, srm_exit         ; If bit is 0, use default start

                ; --- Random Start Room Mod ---

                ld      a, r                ; Hardware entropy
                ld      l, a
                ld      a, (sysvar_FRAMES)  ; Time entropy
                add     a, l                ; Mix them
                and     7                   ; Result 0-7


                ld      e, a
                ld      d, 0
                ld      hl, start_room_init
                add     hl, de              ; Point to table entry
                ld      a, (hl)             ; Get the room ID 
                ld      (player_room), a    ; Set it for spawn
                
srm_exit        ret
                
                

; Table containing 8 potential start rooms
start_room_init:
                db &74, &8F, &66, &00, &24, &85, &27, &76


; place a tombstone at the player position
place_tombstone:
                ld      hl, tombstone1       ; tombstone entities
                ld      de, 8                ; 8 bytes per entity
                ld      b, 4                 ; 4 tombstone slots
loc_95B1:
                ld      a, (hl)
                and     a                    ; free slot?
                jr      z, loc_95B9          ; jump if so
                add     hl, de               ; next slot
                djnz    loc_95B1
                ret
loc_95B9:
                ld      a, &45               ; bright cyan
                ld      (player_attr), a
                push    hl
                ld      (hl), &8f            ; tombstone graphic
                ex      de, hl
                inc     de
                ld      hl, player_room      ; copy remaining details from player entity
                ld      bc, 7                ; 8 bytes minus the graphic we've written
                ldir
                pop     hl                   ; jump return address

; draw entity in HL
draw_entity_hl:
                push    ix
                push    hl
                pop     ix
                call    draw_entity          ; draw entity graphic (no attrs)
                pop     ix
                ret

; Attributes: thunk
h_tombstone:
                jp      draw_16x16           ; draw 16x16 entity

; advance the clock 1 frame
clock_tick:
                ld      a, (sysvar_FRAMES)
                cp      50                   ; 1 second elapsed?
                ret     c                    ; return if not
                sub     50                   ; subtract 1 second
                ld      (sysvar_FRAMES), a   ; store back [this keeps LSB in 0-49 range!]
                ld      hl, clock_seconds
                ld      a, (hl)
                inc     a                    ; add a second
                daa
                ld      (hl), a
                cp      &60                  ; 60 seconds?
                jr      nz, loc_9604         ; jump if not
                ld      (hl), 0              ; reset seconds
                dec     hl
                ld      a, (hl)
                inc     a                    ; add a minute
                daa
                ld      (hl), a
                cp      &60                  ; 60 minutes?
                jr      nz, loc_9604         ; jump if not
                ld      (hl), 0              ; reset minutes
                dec     hl
                ld      a, (hl)
                inc     a                    ; add an hour
                daa
                and     &0f                  ; clip hours to 0-15
                ld      (hl), a
loc_9604:
                ;ld      hl, &58c8            ; timer coords (y,x); changed from &40c8 to &58d0 
                clock_yx equ     &58d0
                ld      hl, clock_yx

; print clock time at position HL
print_clock:
                ;call    xy_to_display        ; convert coords in HL to display address in HL
                ;ld      de, clock_hours
                ;ld      b, 2
                ;call    print_bcd_digit      ; print a single BCD digit
                ;ld      de, clock_seconds
                ;inc     hl
                ;ld      b, 1
                ;jp      print_bcd_bytes      ; print B BCD bytes at DE

                call    xy_to_display        ; Convert coords to screen addr
                ld      de, clock_minutes    ; Point to Minutes
                ld      b, 1                 ; Print ONLY 1 byte (MM)
                call    print_bcd_bytes      ; This draws "MM"
                
                inc     hl                   ; SKIP the colon character on screen
                
                ld      de, clock_seconds    ; Point to Seconds
                ld      b, 1                 ; Print ONLY 1 byte (SS)
                jp      print_bcd_bytes      ; This draws "SS" and returns


; ACG exit door handler
h_acg_exit:

                ld      a, (acg_key_flag)   ; Get the collection state
                and     7                   ; Isolate bits 0, 1, and 2
                cp      7                   ; All three parts present?
                jr      nz, loc_963B        ; If not, show "blocked" message/sfx

                ; --- SUCCESS: OPEN DOOR ---
                call    enter_door          ; Trigger the door transition
                ld      bc, &3020           ; Update area dimensions
                jp      loc_91F5            ; Finalize movement 

loc_963B:
                call    loc_9565
                jp      h_room_item          ; draw room item                



; show game statistics
game_stats:
                call    calc_visited         ; calculate percentage of rooms visited
                
                ld      hl, go_timecap_yx            ; time header at 64,64
                ld      de, time_msg
                call    colour_text          ; show a line of text, first byte is attr
                
                ld      hl, go_scorecap_yx           ; score header at 64,80
                ld      de, score_msg
                call    colour_text          ; show a line of text, first byte is attr
                
                ld      hl, go_roomscap_yx            ; percent header at 64,96
                ld      de, percent_msg
                call    colour_text          ; show a line of text, first byte is attr
                
                ld      hl, digit_charset
                ld      (charset_addr), hl
                
                ld      hl, go_time_yx       ; clock at 128,64
                call    print_clock          ; print clock time at position HL
                
                ld      hl, go_score_yx      ; score at 128,80
                call    print_score          ; print player score at position HL
                
                ld      hl, go_rooms_yx      ; percent at 128,96
                call    xy_to_display        ; convert coords in HL to display address in HL
                ld      de, visited_percent
                ld      b, 1
                jp      print_bcd_bytes      ; print B BCD bytes at DE

time_msg:       db  &45                       ; bright cyan
                db  'TIME    '
                db  '#  '
                db  &a0

score_msg:      db  &45                       ; bright cyan
                db  'SCOR'
                db  &c5

percent_msg:    db  &45                       ; bright cyan
                db  'ROOM'
                db  &D3

;----------------------------------------------------------
