                ld      a, c
                pop     bc
                ret

; add B to DE
add_de_b:
                ld      a, b
                add     a, e
                ld      e, a
                ld      a, d
                adc     a, 0
                ld      d, a
                ret

; subtract B from DE
sbc_de_b:
                ld      a, e
                sub     b
                ld      e, a
                ld      a, d
                sbc     a, 0
                ld      d, a
                ret

