; convert coords in HL to display address in HL
xy_to_display:
                ld      a, l
                rrca
                rrca
                rrca
                and     &1f
                ld      l, a
                ld      a, h
                rlca
                rlca
                and     &e0
                or      l
                ld      l, a
                ld      a, h
                and     7
                ex      af, af'
                ld      a, h
                rrca
                rrca
                rrca
                and     &18
                or      &40
                ld      h, a
                ex      af, af'
                or      h
                ld      h, a
                ret

pixel_line_down:
                inc     h
                ld      a, h
                and     7
                ret     nz
                ld      a, l
                add     a, &20
                ld      l, a
                and     &e0
                ret     z
                ld      a, h
                sub     8
                ld      h, a
                ret

; convert pixel coords in HL to attribute address
xy_to_attr:
                push    bc
                ld      a, l
                rrca
                rrca
                rrca
                and     &1f
                ld      l, a
                ld      a, h
                rlca
                rlca
                ld      c, a
                and     &e0
                or      l
                ld      l, a
                ld      a, c
                and     3
                or      &58
                ld      h, a
