                ld      l, a
                djnz    loc_9CC3
                pop     hl
                jp      plot_l_h             ; plot pixel at L,H
loc_9CD6:
                ex      af, af'
                ld      a, b
                ld      (line_counter), a    ; vert counter
                ex      af, af'
                push    de
                push    hl
                ld      e, b
                ld      d, 0
                ld      l, d
                ld      h, a
                call    line_slope           ; determine Bresenham line slope step
                ld      a, (line_flags)
                bit     1, a                 ; drawing right?
                jr      nz, loc_9CF0         ; jump if so
