                add     a, &10               ; next inventory position
                ld      e, a
                djnz    loc_A143
                ret

; draw inventory item at position DE
draw_inv_item:
                push    bc
                push    de
                push    ix
                ld      ix, entity_to_draw
                ld      a, (hl)              ; entity LSB
                inc     hl
                or      (hl)                 ; object in this slot?
                inc     hl
                ld      a, (hl)
                jr      nz, loc_A15E         ; jump if so
                ld      a, &31               ; blank space
loc_A15E:
                inc     hl
                ld      (ix+0), a            ; set graphic
                ld      (ix+3), e            ; set xpos
                ld      (ix+4), d            ; set ypos
                ld      a, (hl)
                inc     hl
                ld      (ix+5), a            ; set attr
                push    hl
                call    clear_sprite
                call    draw_entity          ; draw entity graphic (no attrs)

                ; --- ACG Safety Check ---
                ;ld      a, (ix+0)            ; Get the Item ID just drawn
                ;cp      &8C                  ; Is it ACG Part 1?
                ;jr      c, .do_attrs         ; If lower, it's a normal item
                ;cp      &8F                  ; Is it above Part 3?
                ;jr      nc, .do_attrs        ; If so, it's a normal item
                
                ;jr      .skip_to_pop         ; It IS an ACG key! Jump over the paint call

.do_attrs:
                
                call    set_entity_attrs     ; paint entity with its current attr colour
 .skip_to_pop:  pop     hl
                pop     ix
                pop     de
                pop     bc
                ret

entity_to_draw: db  0, 0, 0, 0, 0, 0, 0, 0

clear_sprite:
                ld      l, (ix+3)
                ld      h, (ix+4)
                call    xy_to_display        ; convert coords in HL to display address in HL
                ld      b, &14               ; 20 pixels high
loc_A190:
                ld      (hl), 0              ; clear 2 bytes wide
                inc     l
                ld      (hl), 0
                dec     l
                call    pixel_line_up        ; move up 1 display line in HL
                djnz    loc_A190
                ret

; add BC to current score
add_score_bc_bcd:
                ld      hl,  score_bcd+2     ; end of score is 1s
                ld      a, (hl)
                add     a, c                 ; add 10s and 1s
                daa
                ld      (hl), a
                dec     hl
                ld      a, (hl)
                adc     a, b                 ; add 1000s and 100s
                daa
                ld      (hl), a
                dec     hl
                ld      a, (hl)
                adc     a, 0                 ; carry 10000s
                daa

                ; --- MOD: CAP LOGIC ---
                jr      c, force_99999       ; If CPU carry flag set (went past &FF)
                cp      &10                  ; Is the value BCD 100,000 or more?
                jr      c, save_and_continue ; If less than &10, it's a valid 5-digit score

force_99999:
                ld      a, &09               ; Set 10,000s digit to 9
                ld      (score_bcd), a
                ld      a, &99               ; Set others to 99
                ld      (score_bcd+1), a
                ld      (score_bcd+2), a     ; Score is now &09 &99 &99
                jr      loc_A1AE             ; Skip saving 'A' since we manually set it

save_and_continue:
                ld      (hl), a
loc_A1AE:
                ld      hl, digit_charset
                ld      (charset_addr), hl
                ;ld      hl,  display+&10c8
                ld      hl, score_yx
                ret  


; print player score at position HL
print_score:
                call    xy_to_display        ; convert coords in HL to display address in HL
                ld      de, score_bcd
                
                ; --- MOD: DO NOT DISPLAY 6th DIGIT ---
                ld      a, (de)
                and     %00001111            ; Mask out the 100,000s digit (first nibble)
                call    print_char           ; Print & move HL right
                inc     de

                ; --- LOOP FOR REMAINING 4 DIGITS ---


                ld      b, 2                 ; 2 bytes = 4 digits
print_bcd_bytes:
                ld      a, (de)              ; print B BCD bytes at DE
                rrca
                rrca
                rrca
                rrca
                and     &0f
                call    print_char           ; print a single character

; print a single BCD digit
print_bcd_digit:
                ld      a, (de)
                and     &0f
                call    print_char           ; print a single character
                inc     de
                djnz    print_bcd_bytes      ; print B BCD bytes at DE
                ret

; print a single character
print_char:
                push    bc
                push    de
                push    hl
                ld      l, a
                ld      h, 0
                add     hl, hl
                add     hl, hl
                add     hl, hl
                ld      de, (charset_addr)
                add     hl, de
                ex      de, hl
                pop     hl
                ld      b, 8                 ; 8 lines in character cell
loc_A1E5:
                ld      a, (de)
                ld      (hl), a
                inc     de                   ; next source byte
                inc     h                    ; next pixel line
                djnz    loc_A1E5
                pop     de
                pop     bc
                ld      a, h
                sub     8                    ; back to start address
                ld      h, a
                inc     l                    ; next position to the right
                ret

; show a line of text, first byte is attr
colour_text:
                push    hl
                call    xy_to_display        ; convert coords in HL to display address in HL
                ld      a, (de)              ; text attr colour
                ex      af, af'
                inc     de
                exx                          ; display addr in HL
                pop     hl
                call    xy_to_attr           ; convert pixel coords in HL to attribute address
loc_A1FF:
                exx                          ; attr addr in HL'
                ld      a, (de)
                bit     7, a                 ; last character?
                jr      nz, loc_A210         ; jump if so
                call    print_char           ; print a single character
                inc     de
                exx
                ex      af, af'
                ld      (hl), a              ; set attr
                inc     l
                ex      af, af'
                jr      loc_A1FF
loc_A210:
                and     &7f                  ; strip end marker b7
                call    print_char           ; print a single character
                exx
                ex      af, af'
                ld      (hl), a              ; set attr
                ret

; draw side panel background scroll
draw_side_panel:
                                              ; Refactored code to draw side panel in two parts, header and body
                                              ; Header is customised based on character selected
                ld      a, (main_selection)
                and     %00011000             ; Mask bits 3 and 4 - 000DD000, '00'=Knight, '01'=Wizard, '10'=Serf
loc_chk_kni     cp      %00000000             ; Knight selected?
                jp      nz, loc_chk_wiz       ; Jump if not
                ld      de, panel_hdr_kni     ; DE = panel map for Knight
                jr      draw_hdr
loc_chk_wiz     cp      %00001000             ; Wizard selected?
                jp      nz, loc_chk_ser       ; Jump if not
                ld      de, panel_hdr_wiz     ; DE = panel map for Wizard
                jr      draw_hdr
loc_chk_ser     ld      de, panel_hdr_ser     ; DE = panel map for Serf

draw_hdr        ld      hl, panel_chars       ; HL = panel graphics 
                ld      (charset_addr), hl
                ld      hl, &c0               ; H = 0 L = &c0 (192)  H,L = x, y
;                ld      de, panel_data        
                ld      bc, &0803             ; 8x3 colsxrows
                call    loc_A228                  
draw_bod:       ld      hl, panel_chars
                ld      (charset_addr), hl
                ld      hl, &18c0             ; Body coords H (y) = 24 L (x) = 192
                ld      de, panel_body
                ld      bc, &0815             ; Cols/Rows -changed from 0815 to 0818
                call    loc_A228                 
                jp      loc_A1AE

loc_A228:                                    ; Draw panel block (either header or body)
                push    bc
                push    hl
                call    xy_to_display        ; convert coords in HL to display address in HL
loc_A22D:
                ld      a, (de)
                inc     de
                call    print_char           ; print a single character
                djnz    loc_A22D
                pop     hl
                ld      a, h
                add     a, 8
                ld      h, a
                pop     bc
                dec     c
                jr      nz, loc_A228
                ret

; draw side-panel colours, which follow room colour


; side panel layout (H=Y, L=X) for attribute routines
panel_attr_yx    equ     &00c0           ; y=0,   x=192 (&c0)




; --- UPDATED SIDE PANEL LAYOUT (H=Y, L=X) ---

; 1. ACG Key (Now in the middle slot)
;acg_attr_yx     equ     &5ec8           ; Y=94  (Was &58)  ***Bottom half #1***
;acg_key_yx      equ     &75c8           ; Y=117 (Was &6f)

acg_attr_yx     equ     &30c8           ; Y=48
acg_key_yx      equ     &47c8           ; Y=71

; 2. Chicken (Now below ACG Key)
;chicken_attr_yx equ     &7ec8           ; Y=126 (Attribute Top) ***Bottom half #2***
;chicken_yx      equ     &97c8           ; Y=151 (Graphic Bottom)

chicken_attr_yx equ     &60c8           ; Y=96  (Was &48)
chicken_yx      equ     &7fc8           ; Y=127 (Was &67)



; 3. Lives (Now at the bottom)
;lives_attr_yx   equ     &98c8           ; Y=152 (Was &a0)  ***Bottom half #3***
;lives_yx        equ     &afc8           ; Y=175 (Graphic Bottom)

lives_attr_yx   equ     &80c8           ; Y=128
lives_yx        equ     &97c8           ; Y=151


floor_cap_yx     equ     &56c8
floor_yx         equ     &56d0 

time_cap_yx     equ     &5ec8
time_yx         equ     &5ed0

; --- MINIMAP ANCHORS ---
minimap_yx      equ     &98c8            ; The "Master" Coordinate
minimap_y       equ     high(minimap_yx) ; Extract &98 (152)
minimap_x       equ     low(minimap_yx)  ; Extract &C8 (200)


; --- Global Anchor Variables ---
map_anchor_x:    db 0    ; This will hold our "Live" X (e.g., 200 or 10)
map_anchor_y:    db 0    ; This will hold our "Live" Y (e.g., 152 or 20)

;score_cap_yx    equ     &56c8
score_yx        equ     &48d0 

timer_attr_yx   equ     &5ed0


dark_blue       equ      01
bright_white    equ      &47
bright_white_bl equ      &4f  
bright_yellow   equ     &46
bright_yellow_gr equ     &66 
bright_cyan     equ      &45
bright_magenta  equ      &43       


; -----------------------------------------------------------------------------
; Purpose:  Initializes and updates all side-panel attributes (colors).
;           Handles dynamic contrast for the background and checks game flags
;           to highlight collected ACG parts and the current floor.
; Inputs:   (room_attr)      - For contrast calculation.
;           (acg_key_flag)   - Bits 0-2 for key collection status.
;           (current_floor)  - ID (0-4) to highlight floor letters.
; Outputs:  Full attribute refresh of the right-hand side panel (X=24).
; Corrupts: AF, BC, DE, HL
; -----------------------------------------------------------------------------


draw_panel_attrs:
                                             ; COLOUR BACKGROUND
                ld      hl, panel_attr_yx
                call    xy_to_attr           ; convert pixel coords in HL to attribute address
                ld      bc, &0818            ; 8x24
                ld      a, (room_attr)
                cpl                          ; invert for colour contrast
                and     7
                cp      2
                jr      nc, loc_A255         ; red or brighter?
                ld      a, &44               ; change blue to bright green
loc_A255:
                ld      e, a                 ; save attr value
                ;push    de
loc_A257:
                push    bc
                push    hl
loc_A259:
                ld      (hl), e              ; set panel attr
                inc     l
                djnz    loc_A259
                pop     hl
                ld      bc, &20              ; line pitch
                add     hl, bc               ; down a row
                pop     bc                   ;convert pixel coords in HL to attribute address
                dec     c  
                jr      nz, loc_A257
                ;ld      hl, &90C8
                ;call    xy_to_attr
                ;                             ; COLOUR CHAR NAME
                ;ld      a, (room_attr)
                ;ld      bc, &0502            ; MOD: Change &0303 to &0502 for 2 (x) x 5 (y)
                ;call    fill_bc_hl_a         ; fill C rows of B columns of value A at address HL
                ;inc     l
                ;ld      (hl), a
                ;add     hl, de
                ;ld      bc, &0202             ; 2x2 (rosette tail)
                ;call    fill_bc_hl_a         ; fill C rows of B columns of value A at address HL
                ;ld      hl, &98d0
                ;call    xy_to_attr           ; convert pixel coords in HL to attribute address
                ;pop     de
                ;ld      (hl), e              ; rosette centre




                ld      hl, acg_attr_yx     ; Use existing side panel coords
                call    colour_acg_key
      
                ld      hl, lives_attr_yx    ; MOD: Change &7fc8 to &86c8 y,x coords
                call    xy_to_attr           ; convert pixel coords in HL to attribute address
                ld      bc, &0603            ; 6x3
                ld      a, bright_white     ; bright white (LIVES)
                call    fill_bc_hl_a         ; fill C rows of B columns of value A at address HL
                
                ld      hl, chicken_attr_yx  ; MOD: Change &5fc8 to &66c8 y,x coords
                call    xy_to_attr           ; convert pixel coords in HL to attribute address
                ld      bc, &0604            ; 6x4
                ld      a, bright_yellow   ; bright yellow (CHICKEN)
                call    fill_bc_hl_a         ; fill C rows of B columns of value A at address HL
                
                        
                ;ld      hl, score_yx     
                ;call    xy_to_attr           ; convert pixel coords in HL to attribute address
                ;ld      bc, &0501            ; 6x1
                ;ld      a, (bright_white)    ; bright white (score)
                ;call    fill_bc_hl_a         ; fill C rows of B columns of value A at address HL



                ld      hl, floor_cap_yx     ; 58c8 to 5ec8
                call    xy_to_attr           ; convert pixel coords in HL to attribute address
                ld      bc, &0101             ; 6x1
                ld      a, bright_magenta      ; bright cyan (score caption)
                call    fill_bc_hl_a         ; fill C rows of B columns of value A at address HL

                ; --- NEW: HIGHLIGHT CURRENT FLOOR LETTER ---
                ; 1. Reset all 5 letters to Dark Blue first
                ld      hl, floor_yx            ; Your 'C' letter pixel coords
                call    xy_to_attr            ; HL = Attribute address of 'C'
                push    hl                    ; Save for step 2
                ld      a, &01                ; Dark Blue
                ld      (hl), a               ; 'C'
                inc     l
                ld      (hl), a               ; 'B'
                inc     l
                ld      (hl), a               ; 'G'
                inc     l
                ld      (hl), a               ; '1'
                inc     l
                ld      (hl), a               ; 'A'

                ; 2. Highlight the current floor 
                pop     hl                    ; Get 'C' address back
                ld      a, (current_floor)    ; Get Floor ID (0-4)
                cp      &FF                   ; Safety check
                jr      z, .done_floors       ; Skip if no floor set
                
                add     a, l                  ; Offset to current floor
                ld      l, a
                ld      (hl), bright_yellow
.done_floors:

                
                ld      hl, time_cap_yx      ; MOD: Change &38c8 to &48c8 y,x coords
                call    xy_to_attr           ; convert pixel coords in HL to attribute address
                ld      bc, &0101            ; 6x1
                ld      a, bright_magenta    ; bright magenta (time caption)
                call    fill_bc_hl_a         ; fill C rows of B columns of value A at address HL
                
                ld      hl, time_yx          
                call    xy_to_attr 
                ld      bc, &0501
                ld      a, bright_white      
                jp      fill_bc_hl_a         ; fill C rows of B columns of value A at address HL

; draw lives sprites in side panel

 

draw_lives:
                push    ix
                ld      ix, entity_to_draw
                ld      a, (main_selection)
                rlca
                and     &30                  ; extract character type from menu
                or      1                    ; offset to first graphic
                ld      (ix+0), a            ; character type
                ld      (ix+5), &47          ; bright white
                ld      hl, lives_yx         ; coords H=Y, L=X (CHANGED FROM 8dc8 to 95c8)
                ld      (ix+3), l
                ld      (ix+4), h
                ld      a, (lives)
                ld      c, a                 ; number of lives to show
                ld      b, 3                 ; up to 3 lives to draw
loc_A2F2:
                push    bc
                call    clear_sprite         ; clear lives location
                ld      a, c
                and     a                    ; life to show?
                jr      z, loc_A2FD          ; jump if not
                call    draw_entity          ; draw player character
loc_A2FD:
                ld      a, (ix+3)
                add     a, &10               ; offset to next life position
                ld      (ix+3), a
                pop     bc
                dec     c
                jp      p, loc_A30C
                ld      c, 0                 ; min lives is zero
loc_A30C:
                djnz    loc_A2F2             ; draw remaining slots
                pop     ix
                ret


key_part_indices:
                db &8C, &8D, &8E           ; Graphics for the 3 ACG parts




; -----------------------------------------------------------------------------
; draw_acg_key
; -----------------------------------------------------------------------------
; Description: Renders the three parts of the ACG key to the screen.
; Inputs:      DE = Starting YX coordinates (D=Y, E=X)
; Registers:   Modifies AF, BC, DE, HL, IX
; Notes:       Uses the entity_to_draw buffer to interface with draw_entity.
;              Does not call clear_sprite; assumes a clean background.
; -----------------------------------------------------------------------------


draw_acg_key:
                ld      ix, entity_to_draw 
                ld      hl, key_part_indices 
                ;ld      de, acg_key_yx ; Repositioned to calling routine       

                ld      b, 3 

draw_key_loop:
                push    bc 
                push    hl
                push    de      ; We push DE to keep our current Y,X safe

                ; 1. Load graphic index
                ld      a, (hl) 
                ld      (ix+0), a

                ; 2. Assign coordinates/colour
                ld      (ix+3), e    ; X coordinate (from E)
                ld      (ix+4), d    ; Y coordinate (from D)
                

                ; 3. Render
                call    draw_entity 

                pop     de      ; Restore current Y,X
                pop     hl

                ; 4. Advance data pointers
                inc     hl      ; Next graphic ID
                
                ; Move X 16 pixels right for next iteration
                ld      a, e
                add     a, 16
                ld      e, a

                pop     bc 
                djnz    draw_key_loop
                ret



; -----------------------------------------------------------
; Helper Function: colour_acg_key
; Input:  HL = Pointer to the YX coordinate table for the keys
; Output: Updates attribute memory based on acg_key_flag
; -----------------------------------------------------------
colour_acg_key:
                ; --- Part 1 ---
                push    hl                  ; Save anchor (Part 1 coords)
                call    xy_to_attr          
                ld      a, (acg_key_flag)
                bit     0, a                
                ld      a, dark_blue        
                jr      z, .fill_1
                ld      a, bright_yellow    
.fill_1:        ld      bc, &0204           
                call    fill_bc_hl_a

                ; --- Part 2 ---
                pop     hl                  ; Restore anchor
                push    hl                  ; Save anchor again
                ld      a, l
                add     a, 16               ; Offset X by 16 pixels
                ld      l, a                ; Update HL (assumes same Y)
                call    xy_to_attr
                ld      a, (acg_key_flag)
                bit     1, a
                ld      a, dark_blue 
                jr      z, .fill_2
                ld      a, bright_yellow
.fill_2:        ld      bc, &0204           
                call    fill_bc_hl_a

                ; --- Part 3 ---
                pop     hl                  ; Restore anchor
                ld      a, l
                add     a, 32               ; Offset X by 32 pixels
                ld      l, a
                call    xy_to_attr
                ld      a, (acg_key_flag)
                bit     2, a
                ld      a, dark_blue 
                jr      z, .fill_3
                ld      a, bright_yellow
.fill_3:        ld      bc, &0204           
                call    fill_bc_hl_a
                
                ret


; draw menu icons for controls and player acharacters
draw_menu_icons:
                ld      ix, entity_to_draw
                ld      hl, menu_entities    ; entities for icons in the menu position
                ld      b, 9                 ; 3*2 icons for controls, 3 player characters
loc_A31A:
                push    bc
                ld      de, entity_to_draw
                ld      bc, 8
                ldir
                push    hl
                push    de
                call    draw_entity          ; draw entity graphic (no attrs)
                call    set_entity_attrs     ; paint entity with its current attr colour
                pop     de
                pop     hl
                pop     bc
                djnz    loc_A31A
                ret

menu_entities:  db  &32, 0, 0, &20, &4f, &46, 0, 0 ; cursor (left)
                db  &33, 0, 0, &30, &4f, &46, 0, 0 ; cursor (right)
                db  &4a, 0, 0, &20, &37, &44, 0, 0 ; kempston (left)
                db  &4b, 0, 0, &30, &37, &44, 0, 0 ; kempston (right)
                db  &48, 0, 0, &20, &1c, &43, 0, 0 ; keyboard (left)
                db  &49, 0, 0, &30, &1c, &43, 0, 0 ; keyboard (right)
                db  1, 0, 0, &28, &67, &47, 0, 0 ; knight (facing left)
                db  &11, 0, 0, &28, &7f, &47, 0, 0 ; wizard (facing left)
                db  &21, 0, 0, &28, &97, &47, 0, 0 ; serf (facing left)

; determine Bresenham line slope step
line_slope:
                ld      l, h
                ld      h, 0
                exx
                ld      hl, 0
                ld      b, 8
loc_A382:
                exx
                sla     l
                rl      h
                push    hl
                and     a
                sbc     hl, de
                jr      c, loc_A399
                pop     af
                exx
                add     hl, hl
                inc     hl
loc_A391:
                djnz    loc_A382
                push    hl
                exx
                ld      e, l
                ld      d, h
                pop     hl
                ret
loc_A399:
                pop     hl
                exx
                add     hl, hl
                jr      loc_A391

; HL = -DE
minus_de:
                push    de
                ex      de, hl
                ld      hl, 0
                and     a
                sbc     hl, de
                pop     de
                ret

click:
                ld      c, 1                 ; length 1 for a short click
beep:
                ld      a, &10               ; freq B (low is higher), length C
                out     (&fe), a
                push    bc
loc_A3AF:
                djnz    $
                pop     bc
                push    bc
                xor     a
                out     (&fe), a
loc_A3B6:
                djnz    $
                pop     bc
                dec     c
                jr      nz, beep             ; freq B (low is higher), length C
                ret
inventory_sound:
                ld      bc, &4040
                jr      beep                 ; freq B (low is higher), length C

drop_sound:
                ld      bc, &2080            ; long high beep
                jr      beep                 ; freq B (low is higher), length C

acg_key_sound:
                ld      bc, &4020           ; Mid note
                call    beep
                ld      bc, &2020           ; High note
                call    beep
                ret

; play walk clicks if due
walk_sound:
                ld      hl, walk_counter
                inc     (hl)
                ld      a, (hl)
                bit     1, a                 ; low click time?
                jr      z, walk_low          ; jump if so
                and     1                    ; click this frame?
                ret     z                    ; return if not
                ld      bc, &4004            ; high beep
                jr      beep                 ; freq B (low is higher), length C
walk_low:
                and     1                    ; click this frame?
                ret     z                    ; return if not
                ld      bc, &6004            ; low beep
                jr      beep                 ; freq B (low is higher), length C

start_beep:
                ld      bc, &8060            ; long low beep
                jr      beep                 ; freq B (low is higher), length C

; play monster touched sound
touching_sound:
                ld      bc, &6410
queue_sound:
                ld      hl, sound
                ld      (hl), b              ; blank graphic with required sound handler (64 or 65)
                inc     hl
                ld      (hl), c              ; effect counter
                ret

; play next note of sound effect
h_sound_effect:
                dec     (ix+1)               ; hit sound counter
                jr      z, clear_sound
                ld      a, (ix+1)            ; also used for freq and length
                ld      c, a
                xor     &43
                ld      b, a
                jp      beep                 ; freq B (low is higher), length C
clear_sound:
                ld      (ix+0), 0
                ret

; room entry sound effect
entry_sound:
                 ld      bc, &650a
                 jr      queue_sound
;                jr      z, entry_sound_new      ; Z=1 means first visit
;entry_sound_revisit:
;                ld      bc, &6508        ; 08 notes, different pitch range
;                jr      queue_sound
;entry_sound_new:
;                ld      bc, &650a        ; full 10 note sweep
;                jr      queue_sound

; play next note of sound effect
h_sound_effect2:
                dec     (ix+1)               ; effect counter
                jr      z, clear_sound
                ld      a, (ix+1)            ; also used for freq and length
                ld      c, a
                rlca
                rlca
                rlca
                cpl
                xor     &40
                ld      b, a
                jp      beep                 ; freq B (low is higher), length C

; play axe throw sound
axe_sound:
                ld      d, &0c
loc_A41D:
                ld      a, d
                rrca
                ld      b, a                 ; set freq
                call    click
                dec     d
                jr      nz, loc_A41D
                ret

; play sword throw sound
sword_sound:
                ld      d, &10
loc_A429:
                ld      a, d
                rlca
                rlca
                xor     7
                rlca
                rlca
                ld      b, a                 ; set freq
                call    click
                dec     d
                jr      nz, loc_A429
                ret

; play fireball throw sound
fireball_sound:
                ld      d, 8
loc_A43A:
                ld      a, d
                cpl
                rlca
                ld      b, a                 ; set freq
                call    click
                dec     d
                jr      nz, loc_A43A
                ret

; weapon disappearing sound
weapon_pop:
                ld      a, (num_creatures)   ; number of creatures processed this frame
                inc     a
                rlca
                rlca
                rlca
                rlca                         ; * 16
                or      &0f                  ; + 15
                and     &7f                  ; 7-bit
                ld      d, a
loc_A452:
                ld      a, d
                xor     &20
                ld      b, a
                call    click
                dec     d
                ret     z
                dec     d
                ret     z
                jr      loc_A452
appear_sound:
                ld      a, (ix+6)            ; player appearance sound
                cpl
                rlca
                and     &3f
                or      &40
                ld      b, a
                ld      c, &10
                jp      beep                 ; freq B (low is higher), length C
door_sound:
                ld      bc, &0830             ; 48 bytes * 8 bits to output
                ld      hl, 0                ; ROM start
loc_A474:
                ld      e, (hl)              ; read ROM byte for white noise
                inc     hl
                push    bc
loc_A477:
                rrc     e                    ; rotate to use &0eac bit of the byte
                ld      a, e
                and     &10                  ; keep speaker bit
                out     (&fe), a            ; click
                djnz    loc_A477             ; loop for &0eac bit in the byte
                pop     bc
                dec     c                    ; done all bytes?
                jr      nz, loc_A474         ; jump back if not
                ret

eat_sound:
                ld      bc, &a010           ; A0 is blank graphic with food-eaten handler (below)
                jp      queue_sound

; eaten food sound effect handler
h_food_eaten:
                dec     (ix+1)
                jp      m, clear_sound
                ld      c, (ix+1)
                ld      b, 0
                ld      hl, eat_tone_table
                add     hl, bc
                ld      b, (hl)
                ld      c, 8                 ; duration
                jp      beep                 ; freq B (low is higher), length C

eat_tone_table: db  &80, &90, &80, &90, &80, &90, &80, &90
                db  &80, &70, &60, &50, &40, &30, &20, &10

; weapon bounce sound
bounce_sound:
                ld      d, &40
                dec     d
                ret     z
                ld      a, d
                rrca
                rrca
                rrca
                ld      b, a
                ld      c, 4
                jp      beep                 ; freq B (low is higher), length C

